import type { Locale } from './i18n';
import type { Destination } from './destinations-data';

type LocalizedDestination = Partial<Pick<Destination, 'name' | 'tagline' | 'intro' | 'history' | 'country' | 'region' | 'bestSeason' | 'wildlifeHighlights' | 'faqs'>>;

/**
 * Localized copy for destinations added after the original four-destination
 * catalogue. Proper place names remain unchanged; customer-facing prose is
 * supplied for every supported locale so these destinations never fall back
 * to the English source data when a customer changes language.
 */
export const expandedDestinationTranslations: Record<Locale, Record<string, LocalizedDestination>> = {
  en: {},
  it: {
    samburu:{name:'Samburu',tagline:'Bellezza delle terre aride, specie rare del nord e il fiume Ewaso Ng’iro',intro:'La Riserva Nazionale di Samburu offre un netto contrasto con i parchi più umidi del sud del Kenya: colline rocciose, palme doum e pianure dorate si concentrano intorno al fiume Ewaso Ng’iro. È famosa per i Samburu Special Five — zebra di Grevy, giraffa reticolata, gerenuk, struzzo somalo e orice beisa — oltre a leoni, leopardi, elefanti e licaoni.',history:'Samburu è stata istituita come riserva protetta nel 1985. Il paesaggio è da sempre abitato dalle comunità pastorali Samburu, la cui conoscenza dell’acqua stagionale, dei pascoli e della fauna rimane strettamente legata all’ecosistema.',bestSeason:'Giugno–ottobre e gennaio–febbraio sono periodi popolari della stagione secca, quando gli animali si concentrano lungo l’Ewaso Ng’iro. Le stagioni verdi regalano paesaggi spettacolari e uccelli migratori.',wildlifeHighlights:['Samburu Special Five','Elefanti lungo il fiume Ewaso Ng’iro','Leopardi, leoni e licaoni africani','Giraffe reticolate e zebre di Grevy'],faqs:[{q:'Cosa rende Samburu diverso dal Mara?',a:'Samburu offre un paesaggio settentrionale più arido e diverse specie rare nei parchi meridionali, quindi è un eccellente complemento al Mara.'},{q:'Samburu può essere combinato con altri parchi?',a:'Sì. Si combina particolarmente bene con Ol Pejeta, Mount Kenya o Lake Nakuru in un circuito più lungo.'}]},
    'lake-nakuru':{name:'Lake Nakuru',tagline:'Falesie della Rift Valley, rinoceronti e un lago famoso per i fenicotteri',intro:'Il Lake Nakuru National Park circonda un lago alcalino poco profondo nella Great Rift Valley. Praterie, scarpate rocciose, boschi di acacie e zone umide creano una tappa compatta ma ricca di fauna, soprattutto per rinoceronti neri e bianchi, giraffe di Rothschild e numerosi uccelli acquatici.',history:'L’area intorno al Lake Nakuru è diventata parco nazionale nel 1968. Il lago divenne famoso per le immense concentrazioni di fenicotteri, mentre il lavoro di conservazione successivo lo ha trasformato in un importante santuario per rinoceronti e altre specie minacciate.',bestSeason:'Giugno–ottobre e gennaio–febbraio sono periodi secchi affidabili per l’osservazione della fauna. Il numero di fenicotteri varia con livello dell’acqua, condizioni del lago e disponibilità di cibo.',wildlifeHighlights:['Rinoceronti neri e bianchi','Giraffe di Rothschild','Fenicotteri e pellicani quando le condizioni sono favorevoli','Leoni, leopardi, bufali e waterbuck'],faqs:[{q:'I fenicotteri sono sempre a Lake Nakuru?',a:'No. Il loro numero varia con le condizioni dell’acqua e la disponibilità di cibo. Il parco rimane eccellente per rinoceronti, giraffe e altra fauna.'},{q:'Quanto tempo dovremmo fermarci?',a:'Una giornata intera o una notte sono ideali quando si combina Lake Nakuru con il Masai Mara o altre destinazioni della Rift Valley.'}]},
    'naivasha-hells-gate':{name:'Lake Naivasha & Hell’s Gate',tagline:'Acqua dolce, scogliere vulcaniche e una delle migliori avventure attive del Kenya',intro:'Lake Naivasha è un lago d’acqua dolce della Rift Valley circondato da acacie, fattorie floricole e paesaggi vulcanici. Il vicino Hell’s Gate National Park è insolito perché in aree designate si può esplorare a piedi o in bicicletta, tra alte scogliere, fenomeni geotermici e branchi di zebre, giraffe e bufali.',history:'Naivasha fa da secoli parte del paesaggio pastorale e agricolo della Rift Valley. Hell’s Gate è stato proclamato parco nazionale nel 1984 e prende il nome da una stretta apertura tra le scogliere.',bestSeason:'Gennaio–febbraio e giugno–ottobre sono popolari per sentieri più asciutti e panorami più limpidi. Le stagioni verdi possono essere spettacolari per paesaggi e birdwatching.',wildlifeHighlights:['Zebre, giraffe e bufali','Ippopotami nel Lake Naivasha','Riva ricca di uccelli acquatici','Ciclismo e passeggiate tra le scogliere vulcaniche'],faqs:[{q:'Possiamo camminare a Hell’s Gate?',a:'Sì, nelle aree autorizzate e con la guida locale appropriata. È uno dei parchi del Kenya più accessibili per l’esplorazione attiva.'},{q:'Naivasha è adatta alle famiglie?',a:'Sì. Lago, passeggiate semplici, gite in barca e ciclismo a Hell’s Gate aggiungono varietà a un safari familiare.'}]},
    'mount-kenya':{name:'Mount Kenya',tagline:'Foreste d’alta quota, valli alpine e la seconda vetta più alta dell’Africa',intro:'Il Mount Kenya National Park attraversa fitte foreste montane, bambù e brughiere fino alle spettacolari vette vulcaniche. I versanti inferiori ospitano elefanti e bufali, mentre le quote più alte rivelano vegetazione alpina, pareti rocciose e tracce glaciali.',history:'Mount Kenya è un antico vulcano spento e una montagna sacra nella tradizione Kikuyu. Il parco nazionale e la riserva forestale circostante proteggono ecosistemi eccezionali e la montagna è Patrimonio Mondiale UNESCO dal 1997.',bestSeason:'Gennaio–febbraio e giugno–settembre sono generalmente favorevoli al trekking perché più asciutti. Il clima di montagna può cambiare rapidamente in qualsiasi stagione.',wildlifeHighlights:['Elefanti e bufali nella zona forestale','Colobi e altri primati della foresta','Piante alpine e paesaggi d’alta quota','Ricca avifauna montana'],faqs:[{q:'Mount Kenya è solo per alpinisti esperti?',a:'No. Si possono progettare esperienze nelle foreste e nelle brughiere per chi desidera natura e paesaggi senza raggiungere la vetta più alta.'},{q:'Si può combinare con un safari?',a:'Sì. Mount Kenya si combina bene con Samburu, Ol Pejeta, Lake Nakuru e Masai Mara.'}]},
    serengeti:{name:'Serengeti',tagline:'Pianure infinite, terra dei predatori e cuore meridionale della Grande Migrazione',intro:'Il Serengeti National Park è uno dei paesaggi faunistici simbolo dell’Africa: immense pianure erbose interrotte da kopje, corridoi fluviali e boschi. È famoso per la concentrazione dei predatori residenti e per il movimento annuale di gnu, zebre e gazzelle nel più ampio ecosistema Serengeti–Mara.',history:'Il Serengeti è diventato parco nazionale nel 1951 e in seguito è entrato in un sistema di conservazione più ampio con la Ngorongoro Conservation Area. Il nome deriva da un’espressione Maasai comunemente tradotta come “pianure infinite”.',bestSeason:'Giugno–ottobre è popolare per i safari nella stagione secca e le attività migratorie del nord. Gennaio–marzo può essere eccellente nel Serengeti meridionale per le nascite, mentre i tempi esatti cambiano ogni anno.',wildlifeHighlights:['Branchi della Grande Migrazione','Leoni, ghepardi e leopardi','Numerosi elefanti e bufali','Coccodrilli e ippopotami nei sistemi fluviali'],faqs:[{q:'Il Serengeti è uguale al Masai Mara?',a:'No. Sono aree protette diverse in Tanzania e Kenya, ma proteggono un unico sistema ecologico e condividono la migrazione annuale.'},{q:'Quando avviene la migrazione nel Serengeti?',a:'Si muove continuamente nell’ecosistema. Le nascite nel sud sono comunemente associate a gennaio–marzo, mentre gli attraversamenti dei fiumi sono più legati al settore settentrionale nella parte successiva dell’anno.'}]},
    ngorongoro:{name:'Ngorongoro Crater',tagline:'Una caldera vulcanica che racchiude una delle scene faunistiche più concentrate d’Africa',intro:'Il Ngorongoro Crater è una vasta caldera vulcanica le cui praterie, boschi, lago e zone umide racchiuse ospitano una straordinaria densità di fauna. Scendere nel cratere è come entrare in un anfiteatro naturale, dove leoni e iene attraversano le pianure e grandi erbivori si spostano tra acqua e pascoli.',history:'Il cratere si è formato quando un enorme vulcano collassò circa due-tre milioni di anni fa. La Ngorongoro Conservation Area è stata istituita nel 1959 e combina conservazione della fauna, comunità pastorali e patrimonio culturale.',bestSeason:'Giugno–ottobre è una finestra popolare per condizioni limpide e fauna concentrata. Gennaio–marzo porta paesaggi verdi e attività di nascita nell’ecosistema più ampio.',wildlifeHighlights:['Elevata densità di leoni e iene','Elefanti e grandi branchi di bufali','Ippopotami nelle zone umide del cratere','Una delle migliori aree della Tanzania settentrionale per avvistare rinoceronti'],faqs:[{q:'Si può pernottare dentro il cratere?',a:'La maggior parte delle strutture si trova sul bordo del cratere o nell’area circostante, non sul fondo. I safari scendono nel cratere negli orari consentiti.'},{q:'Quanto tempo serve?',a:'Un safari nel cratere può essere svolto in una giornata, soprattutto se combinato con Serengeti o Tarangire.'}]},
    tarangire:{name:'Tarangire',tagline:'Baobab, grandi branchi di elefanti e un fiume che diventa una linfa vitale nella stagione secca',intro:'Il Tarangire National Park è noto per i giganteschi baobab, le zone umide stagionali e un fiume che attira la fauna nei mesi secchi. I branchi di elefanti sono protagonisti, ma il parco offre anche giraffe, zebre, gnu, grandi felini e un’eccezionale avifauna.',history:'Tarangire è diventato parco nazionale nel 1970 dopo anni come riserva di caccia protetta. Il fiume Tarangire e le rotte migratorie circostanti sono fondamentali per l’importanza ecologica del parco, soprattutto nella stagione secca della Tanzania.',bestSeason:'Giugno–ottobre è particolarmente produttivo perché la fauna si concentra intorno al fiume Tarangire e alle poche fonti d’acqua rimaste. Novembre–maggio porta paesaggi più verdi e molti uccelli.',wildlifeHighlights:['Grandi branchi di elefanti','Antichi paesaggi di baobab','Leoni, leopardi e ghepardi','Ricca avifauna e specie migratorie stagionali'],faqs:[{q:'Perché scegliere Tarangire se visitiamo già il Serengeti?',a:'Tarangire offre paesaggi distinti, grandi baobab e ottime osservazioni di elefanti, creando un contrasto interessante in un circuito della Tanzania settentrionale.'},{q:'Tarangire è adatto a un safari breve?',a:'Sì. Funziona molto bene come visita di uno o due giorni partendo dall’area di Arusha.'}]},
    zanzibar:{name:'Zanzibar',tagline:'Storia swahili, isole delle spezie e spiagge turchesi dell’Oceano Indiano',intro:'Zanzibar è l’estensione balneare naturale di un safari nel nord della Tanzania: barriere coralline, spiagge bianche, piantagioni di spezie e i vicoli di Stone Town creano un ritmo completamente diverso dopo le giornate nella savana.',history:'Zanzibar è stato un importante centro commerciale dell’Oceano Indiano, plasmato da influenze africane, arabe, persiane, indiane ed europee. Stone Town conserva questa storia swahili stratificata ed è Patrimonio Mondiale UNESCO.',bestSeason:'Giugno–ottobre è un periodo secco popolare. Anche dicembre–febbraio è caldo e generalmente favorevole. Aprile–maggio porta le grandi piogge e meno visitatori.',wildlifeHighlights:['Delfini e fauna della barriera corallina','Colobi rossi a Unguja','Giardini corallini e spiagge dell’Oceano Indiano','Stone Town e patrimonio delle rotte delle spezie'],faqs:[{q:'Zanzibar può essere combinata con un safari?',a:'Sì. È una delle estensioni balneari più semplici dopo Serengeti, Ngorongoro o Tarangire, grazie ai collegamenti aerei regolari.'},{q:'Zanzibar è solo spiagge?',a:'No. Stone Town, fattorie delle spezie, navigazione in dhow, barriere coralline ed esperienze culturali la rendono una destinazione completa.'}]},
    'queen-elizabeth':{name:'Queen Elizabeth National Park',tagline:'Acque del Kazinga Channel, laghi vulcanici e il classico safari nella savana ugandese',intro:'Il Queen Elizabeth National Park si estende tra Lake Edward e Lake George e combina savana aperta, laghi craterici, boschi e il ricco Kazinga Channel. Le crociere in barca mostrano ippopotami, coccodrilli e moltissimi uccelli acquatici, mentre i safari cercano elefanti, leoni, bufali, kob e altre specie.',history:'Il parco è stato creato nel 1954 e prende il nome dalla regina Elisabetta II. Si trova nell’Albertine Rift, una delle regioni biologicamente più diverse dell’Africa, e collega importanti ecosistemi di savana e foresta dell’Uganda.',bestSeason:'Giugno–settembre e dicembre–febbraio sono popolari per condizioni più asciutte e safari nella savana. I mesi più umidi possono essere ottimi per paesaggi e birdwatching.',wildlifeHighlights:['Leoni arboricoli nel settore Ishasha','Ippopotami e coccodrilli nel Kazinga Channel','Elefanti, bufali e Uganda kob','Eccezionale diversità di uccelli'],faqs:[{q:'Perché visitare Queen Elizabeth invece del Kenya?',a:'Offre il paesaggio distintivo dell’Albertine Rift, eccellenti osservazioni in barca e accesso alle destinazioni forestali e dei primati dell’Uganda.'},{q:'Si può combinare con il trekking dei gorilla?',a:'Sì. Queen Elizabeth è una tappa comune di itinerari più lunghi verso Bwindi.'}]},
    bwindi:{name:'Bwindi Impenetrable Forest',tagline:'Foresta pluviale antica e uno degli incontri con i gorilla più straordinari al mondo',intro:'Bwindi è una foresta pluviale antica e ripida, famosa per il trekking dei gorilla di montagna. Vegetazione fitta, creste nebbiose e biodiversità eccezionale creano un ambiente completamente diverso dai parchi di savana. Il trekking è impegnativo ma profondamente gratificante e segue rigorose regole di conservazione.',history:'Bwindi è diventata parco nazionale nel 1991 e Patrimonio Mondiale UNESCO nel 1994. Il turismo di conservazione sostiene la protezione dei gorilla e le comunità vicine.',bestSeason:'Giugno–agosto e dicembre–febbraio sono spesso preferiti per il trekking perché i sentieri possono essere meno bagnati, ma il trekking opera tutto l’anno e nella foresta la pioggia è sempre possibile.',wildlifeHighlights:['Gorilla di montagna','Scimmie dorate e altri primati nelle vicinanze','Uccelli endemici dell’Albertine Rift','Antica foresta montana'],faqs:[{q:'Il trekking dei gorilla è fisicamente difficile?',a:'Può esserlo. Durata e terreno variano in base alla famiglia di gorilla e alle condizioni. È necessario essere preparati a sentieri ripidi e fangosi.'},{q:'Con quanto anticipo bisogna pianificare i permessi?',a:'I permessi sono limitati e molto richiesti, quindi è consigliabile assicurarli con largo anticipo attraverso le autorità ugandesi competenti o un operatore affidabile.'}]},
    'murchison-falls':{name:'Murchison Falls',tagline:'Il Nilo attraversa una gola stretta prima di esplodere nella savana ugandese',intro:'Il Murchison Falls National Park è la più grande area protetta dell’Uganda ed è definito dal Nilo che attraversa una gola stretta prima di precipitare nelle spettacolari cascate. Crociere, fauna lungo il fiume e ampie pianure di savana formano uno dei paesaggi più distintivi dell’Africa orientale.',history:'Il parco è stato proclamato nel 1952 e fa parte di un più ampio paesaggio protetto lungo il Victoria Nile. Le cascate e il corridoio fluviale sono punti di riferimento del nord dell’Uganda da generazioni.',bestSeason:'Giugno–settembre e dicembre–febbraio sono periodi secchi popolari. Livelli dell’acqua e vegetazione cambiano durante l’anno, modificando l’aspetto delle cascate e del fiume.',wildlifeHighlights:['Ippopotami e coccodrilli del Nilo','Elefanti, giraffe e bufali','Leoni e altri predatori della savana','Safari in barca sul Nilo e punto panoramico delle cascate'],faqs:[{q:'Murchison Falls riguarda solo la cascata?',a:'No. I safari e la crociera sul Nilo sono attrazioni principali, con buone possibilità di vedere elefanti, giraffe, bufali, ippopotami e coccodrilli.'},{q:'Come si inserisce in un viaggio in Uganda?',a:'Può essere combinato con esperienze di scimpanzé o gorilla per un itinerario che unisce savana, fiume e foresta pluviale.'}]},
    akagera:{name:'Akagera',tagline:'Laghi, zone umide di papiro e un ecosistema Big Five in recupero in Rwanda',intro:'Akagera National Park è il contrappunto di savana alle foreste montane del Rwanda. Pianure ondulate, laghi, zone umide di papiro e boschi ospitano elefanti, bufali, giraffe, zebre, antilopi e una popolazione di predatori in crescita. Un safari in barca sul Lake Ihema aggiunge una prospettiva diversa.',history:'Akagera è stata istituita nel 1934 e in seguito ha subito forti perdite di fauna durante periodi di conflitto e sfollamento. Programmi di ripristino e reintroduzione hanno contribuito a ricostruire l’ecosistema, compreso il ritorno di leoni e rinoceronti neri.',bestSeason:'Giugno–settembre è generalmente più secco e favorevole all’osservazione della fauna. Marzo–maggio è più umido e verde, mentre ottobre–febbraio può essere ottimo per il birdwatching.',wildlifeHighlights:['Paesaggio di recupero dei Big Five','Ippopotami e coccodrilli nel Lake Ihema','Giraffe, zebre, elefanti e bufali','Zone umide di papiro e ricca avifauna'],faqs:[{q:'Akagera può essere combinata con il trekking dei gorilla?',a:'Sì. Un itinerario in Rwanda può combinare la savana di Akagera con le esperienze di gorilla o scimmie dorate del Volcanoes National Park.'},{q:'Akagera è adatta a un safari breve?',a:'Sì. La rete stradale compatta e il mix di lago e savana la rendono pratica per due o tre giorni.'}]},
  },
  fr: {
    samburu:{name:'Samburu',tagline:'Beauté des terres arides, espèces rares du nord et rivière Ewaso Ng’iro',intro:'La réserve nationale de Samburu contraste fortement avec les parcs plus humides du sud du Kenya : collines rocheuses, palmiers doum et plaines dorées se concentrent autour de l’Ewaso Ng’iro. Elle est célèbre pour les Samburu Special Five — zèbre de Grévy, girafe réticulée, gerenuk, autruche de Somalie et oryx beisa — ainsi que pour les lions, léopards, éléphants et lycaons.',history:'Samburu est devenue une réserve protégée en 1985. Le paysage est depuis longtemps habité par les communautés pastorales Samburu, dont la connaissance de l’eau saisonnière, des pâturages et de la faune reste liée à l’écosystème.',bestSeason:'Juin–octobre et janvier–février sont des périodes sèches populaires, lorsque les animaux se concentrent autour de l’Ewaso Ng’iro. Les saisons vertes offrent des paysages spectaculaires et des oiseaux migrateurs.',wildlifeHighlights:['Samburu Special Five','Éléphants le long de l’Ewaso Ng’iro','Léopards, lions et lycaons africains','Girafes réticulées et zèbres de Grévy'],faqs:[{q:'Qu’est-ce qui différencie Samburu du Mara ?',a:'Samburu offre un paysage nordique plus aride et plusieurs espèces rarement observées dans le sud du Kenya. C’est donc un excellent complément au Mara.'},{q:'Samburu peut-il être combiné avec d’autres parcs ?',a:'Oui. Il se combine particulièrement bien avec Ol Pejeta, le mont Kenya ou le lac Nakuru.'}]},
    'lake-nakuru':{name:'Lake Nakuru',tagline:'Falaises de la vallée du Rift, rhinocéros et lac célèbre pour ses flamants roses',intro:'Le parc national de Lake Nakuru entoure un lac alcalin peu profond dans la vallée du Rift. Prairies, escarpements rocheux, forêts d’acacias et zones humides forment une étape compacte mais riche, notamment pour les rhinocéros noirs et blancs, les girafes de Rothschild et les oiseaux aquatiques.',history:'La région du lac Nakuru est devenue un parc national en 1968. Le lac est devenu célèbre pour ses immenses rassemblements de flamants, tandis que les efforts de conservation en ont fait un sanctuaire important pour les rhinocéros et d’autres espèces menacées.',bestSeason:'Juin–octobre et janvier–février sont des périodes sèches fiables pour observer la faune. Le nombre de flamants varie selon le niveau du lac, les conditions de l’eau et la nourriture disponible.',wildlifeHighlights:['Rhinocéros noirs et blancs','Girafes de Rothschild','Flamants et pélicans lorsque les conditions sont favorables','Lions, léopards, buffles et cobes à croissant'],faqs:[{q:'Les flamants sont-ils toujours au lac Nakuru ?',a:'Non. Leur nombre varie selon les conditions de l’eau et la nourriture. Le parc reste excellent pour les rhinocéros, les girafes et d’autres animaux.'},{q:'Combien de temps faut-il y rester ?',a:'Une journée complète ou une nuit conviennent très bien lorsqu’on combine Nakuru avec le Masai Mara ou d’autres destinations de la vallée du Rift.'}]},
    'naivasha-hells-gate':{name:'Lake Naivasha & Hell’s Gate',tagline:'Eau douce, falaises volcaniques et l’une des meilleures aventures actives du Kenya',intro:'Le lac Naivasha est un lac d’eau douce de la vallée du Rift entouré d’acacias, de fermes florales et de paysages volcaniques. Le parc voisin de Hell’s Gate est particulier au Kenya : dans les zones autorisées, on peut l’explorer à pied ou à vélo, entre falaises, phénomènes géothermiques et troupeaux de zèbres, girafes et buffles.',history:'Naivasha fait depuis longtemps partie du paysage pastoral et agricole de la vallée du Rift. Hell’s Gate a été classé parc national en 1984 et tire son nom d’une étroite ouverture dans les falaises.',bestSeason:'Janvier–février et juin–octobre sont populaires pour des sentiers plus secs et des vues dégagées. Les saisons vertes sont magnifiques pour les paysages et les oiseaux.',wildlifeHighlights:['Zèbres, girafes et buffles','Hippopotames dans le lac Naivasha','Rives d’eau douce riches en oiseaux','Vélo et randonnée entre les falaises volcaniques'],faqs:[{q:'Peut-on marcher à Hell’s Gate ?',a:'Oui, dans les zones désignées et avec l’accompagnement local approprié. C’est l’un des parcs kenyans les plus accessibles pour une exploration active.'},{q:'Naivasha convient-il aux familles ?',a:'Oui. Le lac, les promenades faciles, les excursions en bateau et le vélo à Hell’s Gate ajoutent de la variété à un safari familial.'}]},
    'mount-kenya':{name:'Mount Kenya',tagline:'Forêts d’altitude, vallées alpines et deuxième plus haut sommet d’Afrique',intro:'Le parc national du mont Kenya traverse des forêts montagnardes, des bambouseraies et des landes jusqu’aux sommets volcaniques spectaculaires. Les pentes basses abritent éléphants et buffles, tandis que les hauteurs révèlent végétation alpine, parois rocheuses et vestiges glaciaires.',history:'Le mont Kenya est un ancien volcan éteint et une montagne sacrée dans la tradition kikuyu. Le parc national et la réserve forestière protègent ses écosystèmes remarquables et la montagne est inscrite au patrimoine mondial de l’UNESCO depuis 1997.',bestSeason:'Janvier–février et juin–septembre sont généralement favorables au trekking grâce à des conditions plus sèches. La météo de montagne peut changer rapidement toute l’année.',wildlifeHighlights:['Éléphants et buffles en forêt','Colobes et autres primates forestiers','Plantes alpines et paysages d’altitude','Avifaune montagnarde diversifiée'],faqs:[{q:'Le mont Kenya est-il réservé aux alpinistes expérimentés ?',a:'Non. Des expériences en forêt et sur les landes peuvent être conçues pour profiter des paysages sans tenter le plus haut sommet.'},{q:'Peut-on le combiner avec un safari ?',a:'Oui. Le mont Kenya se combine naturellement avec Samburu, Ol Pejeta, Lake Nakuru et le Masai Mara.'}]},
    serengeti:{name:'Serengeti',tagline:'Plaines infinies, territoire des prédateurs et cœur méridional de la Grande Migration',intro:'Le parc national du Serengeti est l’un des paysages animaliers emblématiques d’Afrique : vastes plaines herbeuses ponctuées de kopjes, de corridors fluviaux et de boisements. Il est célèbre pour ses prédateurs résidents et pour le déplacement annuel des gnous, zèbres et gazelles dans l’écosystème Serengeti–Mara.',history:'Le Serengeti est devenu parc national en 1951 et a ensuite intégré un système de conservation plus vaste avec la Ngorongoro Conservation Area. Son nom vient d’une expression masaï souvent traduite par « plaines infinies ».',bestSeason:'Juin–octobre est apprécié pour les safaris en saison sèche et l’activité migratoire du nord. Janvier–mars peut être excellent dans le sud pour les naissances, mais le calendrier exact varie chaque année.',wildlifeHighlights:['Troupeaux de la Grande Migration','Lions, guépards et léopards','Importantes populations d’éléphants et de buffles','Crocodiles et hippopotames dans les rivières'],faqs:[{q:'Le Serengeti est-il le même endroit que le Masai Mara ?',a:'Non. Ce sont des zones protégées différentes en Tanzanie et au Kenya, mais elles appartiennent au même système écologique et partagent la migration annuelle.'},{q:'Quand a lieu la migration dans le Serengeti ?',a:'Elle se déplace continuellement dans l’écosystème. Les naissances du sud sont généralement associées à janvier–mars, tandis que les traversées de rivières sont plus liées au nord plus tard dans l’année.'}]},
    ngorongoro:{name:'Ngorongoro Crater',tagline:'Une caldeira volcanique abritant l’une des plus fortes concentrations de faune d’Afrique',intro:'Le cratère du Ngorongoro est une immense caldeira volcanique dont les prairies, bois, lac et marais abritent une densité exceptionnelle d’animaux. Descendre dans le cratère donne l’impression d’entrer dans un amphithéâtre naturel où lions et hyènes parcourent les plaines.',history:'Le cratère s’est formé après l’effondrement d’un immense volcan il y a environ deux à trois millions d’années. La Ngorongoro Conservation Area a été créée en 1959 et associe conservation de la faune, communautés pastorales et patrimoine culturel.',bestSeason:'Juin–octobre est une période populaire pour des conditions claires et une faune concentrée. Janvier–mars apporte des paysages verts et les naissances dans l’écosystème environnant.',wildlifeHighlights:['Forte densité de lions et d’hyènes','Éléphants et grands troupeaux de buffles','Hippopotames dans les zones humides du cratère','Une des meilleures zones du nord de la Tanzanie pour le rhinocéros'],faqs:[{q:'Peut-on dormir à l’intérieur du cratère ?',a:'La plupart des hébergements se trouvent sur le bord du cratère ou dans la zone de conservation, pas sur le fond. Les safaris descendent aux heures autorisées.'},{q:'Combien de temps faut-il ?',a:'Une excursion dans le cratère peut tenir sur une journée, notamment lorsqu’elle est combinée au Serengeti ou à Tarangire.'}]},
    tarangire:{name:'Tarangire',tagline:'Baobabs, grands troupeaux d’éléphants et rivière vitale pendant la saison sèche',intro:'Le parc national de Tarangire est connu pour ses baobabs géants, ses zones humides saisonnières et sa rivière qui attire la faune pendant les mois secs. Les troupeaux d’éléphants sont emblématiques, mais le parc offre aussi girafes, zèbres, gnous, grands félins et une avifaune exceptionnelle.',history:'Tarangire est devenu parc national en 1970 après des années comme réserve de chasse protégée. La rivière Tarangire et les routes migratoires environnantes sont essentielles à l’importance écologique du parc, surtout pendant la saison sèche tanzanienne.',bestSeason:'Juin–octobre est particulièrement favorable car les animaux se rassemblent autour de la rivière Tarangire et des sources d’eau restantes. Novembre–mai offre des paysages plus verts et beaucoup d’oiseaux.',wildlifeHighlights:['Grands troupeaux d’éléphants','Anciens paysages de baobabs','Lions, léopards et guépards','Oiseaux nombreux et espèces migratrices saisonnières'],faqs:[{q:'Pourquoi choisir Tarangire si nous visitons déjà le Serengeti ?',a:'Tarangire possède des paysages distincts, de grands baobabs et une excellente observation des éléphants, offrant un contraste intéressant.'},{q:'Tarangire convient-il à un safari court ?',a:'Oui. Il fonctionne très bien comme visite d’un ou deux jours depuis la région d’Arusha.'}]},
    zanzibar:{name:'Zanzibar',tagline:'Histoire swahilie, îles aux épices et plages turquoise de l’océan Indien',intro:'Zanzibar est le prolongement balnéaire naturel d’un safari dans le nord de la Tanzanie : récifs coralliens, plages de sable blanc, plantations d’épices et ruelles de Stone Town offrent un rythme totalement différent après les journées dans la brousse.',history:'Zanzibar fut un important centre commercial de l’océan Indien, marqué par des influences africaines, arabes, persanes, indiennes et européennes. Stone Town conserve cette histoire swahilie et est inscrite au patrimoine mondial de l’UNESCO.',bestSeason:'Juin–octobre est une période sèche populaire. Décembre–février est également chaud et généralement favorable. Avril–mai apporte les longues pluies et moins de visiteurs.',wildlifeHighlights:['Dauphins et vie des récifs','Colobes rouges à Unguja','Jardins coralliens et plages de l’océan Indien','Stone Town et patrimoine des routes des épices'],faqs:[{q:'Zanzibar peut-elle être combinée avec un safari ?',a:'Oui. C’est l’une des extensions balnéaires les plus faciles après le Serengeti, le Ngorongoro ou Tarangire, grâce aux vols réguliers.'},{q:'Zanzibar se résume-t-elle aux plages ?',a:'Non. Stone Town, les fermes d’épices, les dhows, les récifs et les expériences culturelles en font une destination complète.'}]},
    'queen-elizabeth':{name:'Queen Elizabeth National Park',tagline:'Eaux du Kazinga Channel, lacs de cratère et safari classique dans la savane ougandaise',intro:'Le Queen Elizabeth National Park s’étend entre les lacs Edward et George et combine savane ouverte, lacs de cratère, boisements et Kazinga Channel riche en faune. Les croisières révèlent hippopotames, crocodiles et de nombreux oiseaux aquatiques, tandis que les safaris recherchent éléphants, lions, buffles et cobes.',history:'Le parc a été créé en 1954 et nommé en l’honneur de la reine Elizabeth II. Il se situe dans l’Albertine Rift, l’une des régions les plus riches en biodiversité d’Afrique.',bestSeason:'Juin–septembre et décembre–février sont populaires pour des conditions plus sèches et l’observation de la faune. Les mois humides peuvent être magnifiques pour les paysages et les oiseaux.',wildlifeHighlights:['Lions arboricoles dans le secteur d’Ishasha','Hippopotames et crocodiles du Kazinga Channel','Éléphants, buffles et cobes d’Ouganda','Diversité exceptionnelle d’oiseaux'],faqs:[{q:'Pourquoi visiter Queen Elizabeth plutôt que le Kenya ?',a:'Il offre les paysages de l’Albertine Rift, d’excellentes observations en bateau et un accès aux destinations forestières et aux primates de l’Ouganda.'},{q:'Peut-on le combiner avec les gorilles ?',a:'Oui. Queen Elizabeth est une étape fréquente des itinéraires plus longs vers Bwindi.'}]},
    bwindi:{name:'Bwindi Impenetrable Forest',tagline:'Forêt tropicale ancienne et rencontre exceptionnelle avec les gorilles de montagne',intro:'Bwindi est une forêt tropicale ancienne et escarpée célèbre pour le trekking des gorilles de montagne. Végétation dense, crêtes brumeuses et biodiversité remarquable offrent une expérience très différente des parcs de savane. Le trekking est exigeant mais profondément gratifiant.',history:'Bwindi a été classée parc national en 1991 puis inscrite au patrimoine mondial de l’UNESCO en 1994. Le tourisme de conservation contribue fortement à la protection des gorilles et aux communautés voisines.',bestSeason:'Juin–août et décembre–février sont souvent privilégiés car les sentiers peuvent être moins humides, mais le trekking fonctionne toute l’année et la pluie reste possible.',wildlifeHighlights:['Gorilles de montagne','Singes dorés et autres primates à proximité','Oiseaux endémiques de l’Albertine Rift','Ancienne forêt montagnarde'],faqs:[{q:'Le trekking des gorilles est-il physiquement difficile ?',a:'Il peut l’être. La durée et le terrain varient selon la famille de gorilles et les conditions. Il faut être prêt pour des sentiers forestiers raides et boueux.'},{q:'Combien de temps à l’avance faut-il prévoir les permis ?',a:'Les permis sont limités et très demandés. Il est conseillé de les obtenir longtemps à l’avance auprès des autorités ou d’un opérateur fiable.'}]},
    'murchison-falls':{name:'Murchison Falls',tagline:'Le Nil se resserre dans une gorge avant de jaillir au cœur de la savane ougandaise',intro:'Le Murchison Falls National Park est la plus grande aire protégée d’Ouganda. Le Nil y traverse une gorge étroite avant de tomber en cascades puissantes. Croisières, faune des berges et vastes plaines de savane composent un paysage emblématique d’Afrique de l’Est.',history:'Le parc a été classé en 1952 et fait partie d’un paysage protégé plus vaste le long du Victoria Nile. Les chutes et le corridor fluvial sont des repères majeurs du nord de l’Ouganda depuis des générations.',bestSeason:'Juin–septembre et décembre–février sont des périodes sèches populaires. Les niveaux d’eau et la végétation changent au fil de l’année et modifient l’apparence des chutes.',wildlifeHighlights:['Hippopotames et crocodiles du Nil','Éléphants, girafes et buffles','Lions et autres prédateurs de savane','Safari en bateau sur le Nil et point de vue sur les chutes'],faqs:[{q:'Murchison Falls concerne-t-il seulement la cascade ?',a:'Non. Les safaris et la croisière sur le Nil sont des attractions majeures, avec de bonnes chances de voir éléphants, girafes, buffles, hippopotames et crocodiles.'},{q:'Comment l’intégrer à un voyage en Ouganda ?',a:'Il peut être associé aux chimpanzés ou aux gorilles pour un itinéraire mêlant savane, rivière et forêt tropicale.'}]},
    akagera:{name:'Akagera',tagline:'Lacs, marais de papyrus et écosystème des Big Five en restauration au Rwanda',intro:'Le parc national d’Akagera est le pendant savane des forêts montagneuses du Rwanda. Plaines ondulées, lacs, marais de papyrus et boisements abritent éléphants, buffles, girafes, zèbres, antilopes et une population de prédateurs en croissance. Une excursion en bateau sur le lac Ihema offre une autre perspective.',history:'Akagera a été créé en 1934 et a ensuite subi de lourdes pertes de faune pendant les périodes de conflit et de déplacement. Les programmes de restauration et de réintroduction ont contribué à reconstruire l’écosystème, notamment avec le retour des lions et des rhinocéros noirs.',bestSeason:'Juin–septembre est généralement plus sec et favorable aux safaris. Mars–mai est plus humide et vert, tandis qu’octobre–février peut être excellent pour les oiseaux et les paysages luxuriants.',wildlifeHighlights:['Paysage de restauration des Big Five','Hippopotames et crocodiles du lac Ihema','Girafes, zèbres, éléphants et buffles','Marais de papyrus et riche avifaune'],faqs:[{q:'Akagera peut-il être combiné avec les gorilles ?',a:'Oui. Un voyage au Rwanda peut combiner la savane d’Akagera avec les gorilles ou les singes dorés du parc national des Volcans.'},{q:'Akagera convient-il à un safari court ?',a:'Oui. Son réseau routier compact et son mélange de lac et de savane sont pratiques pour deux ou trois jours.'}]},
  },
  es: {
    samburu:{name:'Samburu',tagline:'Belleza de tierras áridas, especies raras del norte y el río Ewaso Ng’iro',intro:'La Reserva Nacional de Samburu contrasta con los parques más húmedos del sur de Kenia: colinas rocosas, palmeras doum y llanuras doradas se concentran alrededor del río Ewaso Ng’iro. Es famosa por los Samburu Special Five — cebra de Grevy, jirafa reticulada, gerenuc, avestruz somalí y órice beisa — además de leones, leopardos, elefantes y licaones.',history:'Samburu se convirtió en reserva protegida en 1985. El paisaje ha sido hogar de comunidades pastoriles Samburu durante generaciones, cuya experiencia con el agua estacional, los pastos y la fauna sigue ligada al ecosistema.',bestSeason:'Junio–octubre y enero–febrero son periodos secos populares, cuando los animales se concentran junto al Ewaso Ng’iro. Las estaciones verdes ofrecen paisajes espectaculares y aves migratorias.',wildlifeHighlights:['Samburu Special Five','Elefantes junto al Ewaso Ng’iro','Leopardos, leones y licaones africanos','Jirafa reticulada y cebra de Grevy'],faqs:[{q:'¿Qué diferencia a Samburu del Mara?',a:'Samburu ofrece un paisaje norteño más seco y especies que rara vez se ven en el sur de Kenia, por lo que complementa muy bien al Mara.'},{q:'¿Se puede combinar Samburu con otros parques?',a:'Sí. Combina especialmente bien con Ol Pejeta, Mount Kenya o Lake Nakuru en un circuito más largo.'}]},
    'lake-nakuru':{name:'Lake Nakuru',tagline:'Acantilados del Valle del Rift, rinocerontes y un lago famoso por sus flamencos',intro:'El Parque Nacional de Lake Nakuru rodea un lago alcalino poco profundo del Gran Valle del Rift. Praderas, escarpes rocosos, bosques de acacias y humedales forman una parada compacta pero rica en fauna, especialmente rinocerontes negros y blancos, jirafas de Rothschild y aves acuáticas.',history:'La zona de Lake Nakuru se convirtió en parque nacional en 1968. El lago ganó fama internacional por sus enormes concentraciones de flamencos, mientras que la conservación posterior lo convirtió en un santuario importante para rinocerontes y otras especies amenazadas.',bestSeason:'Junio–octubre y enero–febrero son periodos secos fiables para observar fauna. El número de flamencos cambia según el nivel del agua, las condiciones del lago y el alimento disponible.',wildlifeHighlights:['Rinocerontes negros y blancos','Jirafa de Rothschild','Flamencos y pelícanos cuando las condiciones son favorables','León, leopardo, búfalo y waterbuck'],faqs:[{q:'¿Siempre hay flamencos en Lake Nakuru?',a:'No. Su número depende de las condiciones del agua y del alimento. El parque sigue siendo excelente para rinocerontes, jirafas y otra fauna.'},{q:'¿Cuánto tiempo deberíamos quedarnos?',a:'Un día completo o una noche funcionan muy bien al combinar Nakuru con Masai Mara u otros destinos del Valle del Rift.'}]},
    'naivasha-hells-gate':{name:'Lake Naivasha & Hell’s Gate',tagline:'Agua dulce, acantilados volcánicos y una de las mejores aventuras activas de Kenia',intro:'Lake Naivasha es un lago de agua dulce del Valle del Rift rodeado de acacias, granjas de flores y paisajes volcánicos. El cercano Parque Nacional Hell’s Gate es especial porque, en zonas autorizadas, se puede explorar a pie o en bicicleta entre altos acantilados, fenómenos geotérmicos y cebras, jirafas y búfalos.',history:'Naivasha forma parte desde hace mucho del paisaje pastoril y agrícola del Valle del Rift. Hell’s Gate fue declarado parque nacional en 1984 y toma su nombre de una estrecha abertura entre los acantilados.',bestSeason:'Enero–febrero y junio–octubre son populares por los senderos más secos y las vistas despejadas. Las estaciones verdes pueden ser magníficas para paisajes y aves.',wildlifeHighlights:['Cebras, jirafas y búfalos','Hipopótamos en Lake Naivasha','Orillas de agua dulce ricas en aves','Ciclismo y caminatas entre acantilados volcánicos'],faqs:[{q:'¿Podemos caminar en Hell’s Gate?',a:'Sí, en las zonas designadas y con la orientación local adecuada. Es uno de los parques de Kenia más accesibles para explorar activamente.'},{q:'¿Naivasha es adecuado para familias?',a:'Sí. El lago, los paseos suaves, los barcos y el ciclismo en Hell’s Gate aportan variedad a un safari familiar.'}]},
    'mount-kenya':{name:'Mount Kenya',tagline:'Bosques de altura, valles alpinos y la segunda cumbre más alta de África',intro:'El Parque Nacional de Mount Kenya atraviesa bosques montanos, bambú y brezales hasta llegar a espectaculares cumbres volcánicas. Las laderas bajas albergan elefantes y búfalos, mientras las zonas altas muestran vegetación alpina, paredes rocosas y restos glaciares.',history:'Mount Kenya es un antiguo volcán extinguido y una montaña sagrada para la tradición kikuyu. El parque y la reserva forestal protegen ecosistemas excepcionales y la montaña es Patrimonio Mundial de la UNESCO desde 1997.',bestSeason:'Enero–febrero y junio–septiembre suelen ser favorables para el trekking por sus condiciones más secas. El clima de montaña puede cambiar rápidamente en cualquier época.',wildlifeHighlights:['Elefantes y búfalos en la zona forestal','Colobos y otros primates','Plantas alpinas y paisajes de altura','Diversidad de aves de montaña'],faqs:[{q:'¿Mount Kenya es solo para alpinistas experimentados?',a:'No. Se pueden diseñar experiencias en bosque y brezales para disfrutar de la naturaleza sin intentar la cumbre más alta.'},{q:'¿Se puede combinar con un safari?',a:'Sí. Mount Kenya combina naturalmente con Samburu, Ol Pejeta, Lake Nakuru y Masai Mara.'}]},
    serengeti:{name:'Serengeti',tagline:'Llanuras infinitas, territorio de depredadores y corazón meridional de la Gran Migración',intro:'El Parque Nacional del Serengeti es uno de los grandes paisajes de fauna de África: enormes llanuras de hierba interrumpidas por kopjes, corredores fluviales y bosques. Es famoso por sus depredadores residentes y por el movimiento anual de ñus, cebras y gacelas por el ecosistema Serengeti–Mara.',history:'Serengeti se convirtió en parque nacional en 1951 y posteriormente formó parte de un sistema de conservación más amplio con el Área de Conservación de Ngorongoro. El nombre procede de una expresión masái que suele traducirse como “llanuras infinitas”.',bestSeason:'Junio–octubre es popular para el safari en estación seca y la actividad migratoria del norte. Enero–marzo puede ser excelente en el Serengeti sur para los nacimientos, pero las fechas cambian cada año.',wildlifeHighlights:['Manadas de la Gran Migración','Leones, guepardos y leopardos','Grandes poblaciones de elefantes y búfalos','Cocodrilos e hipopótamos en los ríos'],faqs:[{q:'¿El Serengeti es lo mismo que Masai Mara?',a:'No. Son áreas protegidas distintas de Tanzania y Kenia, pero forman un mismo sistema ecológico y comparten la migración anual.'},{q:'¿Cuándo ocurre la migración en Serengeti?',a:'Se desplaza continuamente por el ecosistema. Los nacimientos del sur suelen asociarse con enero–marzo, mientras los cruces de ríos se relacionan más con el sector norte posteriormente.'}]},
    ngorongoro:{name:'Ngorongoro Crater',tagline:'Una caldera volcánica con una de las mayores concentraciones de fauna de África',intro:'El Cráter del Ngorongoro es una enorme caldera volcánica cuyas praderas, bosques, lago y humedales sostienen una densidad extraordinaria de fauna. Descender al cráter es como entrar en un anfiteatro natural donde leones e hienas recorren las llanuras y los herbívoros se mueven entre agua y pastos.',history:'El cráter se formó tras el colapso de un enorme volcán hace aproximadamente dos o tres millones de años. El Área de Conservación de Ngorongoro se creó en 1959 y combina conservación, comunidades pastoriles y patrimonio cultural.',bestSeason:'Junio–octubre es una ventana popular por las condiciones claras y la fauna concentrada. Enero–marzo ofrece paisajes verdes y nacimientos en el ecosistema más amplio.',wildlifeHighlights:['Alta densidad de leones e hienas','Elefantes y grandes manadas de búfalos','Hipopótamos en los humedales del cráter','Una de las mejores zonas del norte de Tanzania para rinocerontes'],faqs:[{q:'¿Se puede dormir dentro del cráter?',a:'La mayoría de alojamientos está en el borde o en el área de conservación circundante, no en el fondo. Los safaris descienden al cráter durante las horas permitidas.'},{q:'¿Cuánto tiempo necesitamos?',a:'Una excursión por el cráter puede ocupar un día, especialmente combinada con Serengeti o Tarangire.'}]},
    tarangire:{name:'Tarangire',tagline:'Baobabs, grandes manadas de elefantes y un río vital en la estación seca',intro:'El Parque Nacional de Tarangire es conocido por sus enormes baobabs, humedales estacionales y un río que atrae a la fauna durante los meses secos. Los elefantes son protagonistas, pero también hay jirafas, cebras, ñus, grandes felinos y una avifauna excepcional.',history:'Tarangire se convirtió en parque nacional en 1970 tras años como reserva de caza protegida. El río Tarangire y las rutas migratorias cercanas son fundamentales para su importancia ecológica, especialmente durante la estación seca de Tanzania.',bestSeason:'Junio–octubre es especialmente productivo porque la fauna se concentra alrededor del río Tarangire y las fuentes de agua restantes. Noviembre–mayo ofrece paisajes más verdes y muchas aves.',wildlifeHighlights:['Grandes manadas de elefantes','Antiguos paisajes de baobabs','Leones, leopardos y guepardos','Abundantes aves y especies migratorias estacionales'],faqs:[{q:'¿Por qué elegir Tarangire si ya visitamos Serengeti?',a:'Tarangire tiene un paisaje distinto, grandes baobabs y excelentes avistamientos de elefantes, creando un contraste valioso.'},{q:'¿Tarangire sirve para un safari corto?',a:'Sí. Funciona muy bien como visita de uno o dos días desde el área de Arusha.'}]},
    zanzibar:{name:'Zanzibar',tagline:'Historia swahili, islas de especias y playas turquesas del océano Índico',intro:'Zanzibar es la extensión de playa natural de un safari por el norte de Tanzania: arrecifes de coral, playas blancas, plantaciones de especias y las calles de Stone Town crean un ritmo diferente después de los días en la sabana.',history:'Zanzibar fue un importante centro comercial del océano Índico, influido por culturas africanas, árabes, persas, indias y europeas. Stone Town conserva esta historia swahili y es Patrimonio Mundial de la UNESCO.',bestSeason:'Junio–octubre es un periodo seco popular. Diciembre–febrero también es cálido y suele ser favorable. Abril–mayo trae las lluvias largas y menos visitantes.',wildlifeHighlights:['Delfines y vida de arrecife','Colobos rojos en Unguja','Jardines de coral y playas del océano Índico','Stone Town y patrimonio de las rutas de especias'],faqs:[{q:'¿Zanzibar se puede combinar con un safari?',a:'Sí. Es una de las extensiones de playa más fáciles después de Serengeti, Ngorongoro o Tarangire gracias a los vuelos regulares.'},{q:'¿Zanzibar es solo playas?',a:'No. Stone Town, las granjas de especias, los dhows, los arrecifes y las experiencias culturales la convierten en un destino completo.'}]},
    'queen-elizabeth':{name:'Queen Elizabeth National Park',tagline:'Aguas del Kazinga Channel, lagos de cráter y el safari clásico de la sabana ugandesa',intro:'El Parque Nacional Queen Elizabeth se extiende entre Lake Edward y Lake George y combina sabana abierta, lagos de cráter, bosques y el rico Kazinga Channel. Los paseos en barco muestran hipopótamos, cocodrilos y numerosas aves acuáticas, mientras los safaris buscan elefantes, leones, búfalos y kob.',history:'El parque se creó en 1954 y recibió el nombre de la reina Isabel II. Se encuentra en el Albertine Rift, una de las regiones con mayor biodiversidad de África.',bestSeason:'Junio–septiembre y diciembre–febrero son populares por condiciones más secas y buena observación de fauna. Los meses húmedos pueden ser excelentes para paisajes y aves.',wildlifeHighlights:['Leones trepadores en el sector Ishasha','Hipopótamos y cocodrilos del Kazinga Channel','Elefantes, búfalos y kob de Uganda','Gran diversidad de aves'],faqs:[{q:'¿Por qué visitar Queen Elizabeth en lugar de Kenia?',a:'Ofrece paisajes diferentes del Albertine Rift, excelentes experiencias en barco y acceso a destinos forestales y de primates de Uganda.'},{q:'¿Se puede combinar con gorilas?',a:'Sí. Queen Elizabeth es una etapa habitual de itinerarios largos hacia Bwindi.'}]},
    bwindi:{name:'Bwindi Impenetrable Forest',tagline:'Selva tropical antigua y uno de los encuentros con gorilas más extraordinarios del mundo',intro:'Bwindi es una antigua selva tropical y montañosa famosa por el trekking de gorilas de montaña. La vegetación densa, las crestas brumosas y la biodiversidad hacen que sea completamente diferente de los parques de sabana. El trekking es exigente pero profundamente gratificante.',history:'Bwindi fue declarado parque nacional en 1991 y Patrimonio Mundial de la UNESCO en 1994. El turismo de conservación ayuda a proteger a los gorilas y a las comunidades vecinas.',bestSeason:'Junio–agosto y diciembre–febrero suelen preferirse porque los senderos pueden estar menos mojados, pero el trekking funciona todo el año y siempre puede llover.',wildlifeHighlights:['Gorilas de montaña','Monos dorados y otros primates cercanos','Aves endémicas del Albertine Rift','Antigua selva montana'],faqs:[{q:'¿El trekking de gorilas es físicamente difícil?',a:'Puede serlo. La duración y el terreno dependen de la familia de gorilas y las condiciones. Hay que estar preparado para senderos forestales empinados y embarrados.'},{q:'¿Con cuánto tiempo hay que planificar los permisos?',a:'Los permisos son limitados y muy solicitados. Conviene conseguirlos con bastante antelación mediante las autoridades correspondientes o un operador fiable.'}]},
    'murchison-falls':{name:'Murchison Falls',tagline:'El Nilo se estrecha en un cañón antes de caer con fuerza sobre la sabana de Uganda',intro:'El Parque Nacional Murchison Falls es el área protegida más grande de Uganda. El Nilo atraviesa una garganta estrecha antes de caer en unas cascadas espectaculares. Paseos en barco, fauna ribereña y amplias llanuras de sabana forman uno de los paisajes más distintivos de África oriental.',history:'El parque fue declarado en 1952 y forma parte de un paisaje protegido más amplio a lo largo del Victoria Nile. Las cascadas y el corredor fluvial son hitos importantes del norte de Uganda desde hace generaciones.',bestSeason:'Junio–septiembre y diciembre–febrero son periodos secos populares. Los niveles de agua y la vegetación cambian durante el año y modifican el aspecto de las cascadas y el río.',wildlifeHighlights:['Hipopótamos y cocodrilos del Nilo','Elefantes, jirafas y búfalos','Leones y otros depredadores de sabana','Safari en barco por el Nilo y mirador de las cataratas'],faqs:[{q:'¿Murchison Falls es solo la cascada?',a:'No. Los safaris y el crucero por el Nilo son grandes atractivos, con buenas posibilidades de ver elefantes, jirafas, búfalos, hipopótamos y cocodrilos.'},{q:'¿Cómo encaja en un viaje por Uganda?',a:'Puede combinarse con experiencias de chimpancés o gorilas para unir sabana, río y selva tropical.'}]},
    akagera:{name:'Akagera',tagline:'Lagos, humedales de papiro y un ecosistema de Big Five en recuperación en Ruanda',intro:'El Parque Nacional Akagera es el contrapunto de sabana a los bosques montanos de Ruanda. Llanuras onduladas, lagos, humedales de papiro y bosques albergan elefantes, búfalos, jirafas, cebras, antílopes y una población creciente de depredadores. Un paseo en barco por Lake Ihema ofrece otra perspectiva.',history:'Akagera se estableció en 1934 y posteriormente sufrió grandes pérdidas de fauna durante periodos de conflicto y desplazamiento. Los programas de restauración y reintroducción han ayudado a recuperar el ecosistema, incluido el regreso de leones y rinocerontes negros.',bestSeason:'Junio–septiembre suele ser más seco y bueno para ver fauna. Marzo–mayo es más húmedo y verde, mientras octubre–febrero puede ser excelente para aves y paisajes frondosos.',wildlifeHighlights:['Paisaje de recuperación de los Big Five','Hipopótamos y cocodrilos de Lake Ihema','Jirafas, cebras, elefantes y búfalos','Humedales de papiro y rica avifauna'],faqs:[{q:'¿Akagera se puede combinar con gorilas?',a:'Sí. Un viaje por Ruanda puede combinar la sabana de Akagera con gorilas o monos dorados del Parque Nacional de los Volcanes.'},{q:'¿Akagera es bueno para un safari corto?',a:'Sí. Su red de caminos compacta y la combinación de lago y sabana lo hacen práctico para dos o tres días.'}]},
  },
  de: {
    samburu:{name:'Samburu',tagline:'Trockene Landschaften, seltene Arten des Nordens und der Ewaso-Ng’iro-Fluss',intro:'Das Samburu National Reserve bildet einen starken Kontrast zu Kenias feuchteren südlichen Parks: felsige Hügel, Doumpalmen und goldene Ebenen sammeln sich am Ewaso Ng’iro. Berühmt ist das Reservat für die Samburu Special Five — Grevyzebra, Netzgiraffe, Gerenuk, Somali-Strauß und Beisa-Oryx — sowie für Löwen, Leoparden, Elefanten und Wildhunde.',history:'Samburu wurde 1985 als Schutzgebiet eingerichtet. Die Landschaft ist seit Langem Heimat der pastoralen Samburu-Gemeinschaften, deren Wissen über saisonales Wasser, Weideflächen und Wildtiere eng mit dem Ökosystem verbunden bleibt.',bestSeason:'Juni–Oktober und Januar–Februar sind beliebte Trockenzeiten, wenn sich Tiere am Ewaso Ng’iro konzentrieren. Die grünen Jahreszeiten bieten dramatische Landschaften und Zugvögel.',wildlifeHighlights:['Samburu Special Five','Elefanten am Ewaso Ng’iro','Leopard, Löwe und Afrikanischer Wildhund','Netzgiraffe und Grevyzebra'],faqs:[{q:'Was unterscheidet Samburu vom Mara?',a:'Samburu bietet eine trockenere Landschaft im Norden und mehrere Arten, die im Süden selten zu sehen sind. Es ergänzt den Mara hervorragend.'},{q:'Kann Samburu mit anderen Parks kombiniert werden?',a:'Ja. Samburu lässt sich besonders gut mit Ol Pejeta, Mount Kenya oder Lake Nakuru verbinden.'}]},
    'lake-nakuru':{name:'Lake Nakuru',tagline:'Rift-Valley-Klippen, Nashörner und ein für Flamingos berühmter See',intro:'Der Lake Nakuru National Park liegt rund um einen flachen alkalischen See im Great Rift Valley. Grasland, felsige Steilhänge, Akazienwälder und Feuchtgebiete machen ihn zu einem kompakten, aber lohnenden Wildtiergebiet, besonders für schwarze und weiße Nashörner, Rothschild-Giraffen und Wasservögel.',history:'Die Region um Lake Nakuru wurde 1968 zum Nationalpark. Der See wurde durch riesige Flamingoansammlungen international bekannt; spätere Schutzarbeit machte den Park zu einem wichtigen Nashornschutzgebiet.',bestSeason:'Juni–Oktober und Januar–Februar sind zuverlässige Trockenzeiten für Wildbeobachtungen. Die Flamingozahl hängt von Wasserstand, Seebedingungen und Nahrungsverfügbarkeit ab.',wildlifeHighlights:['Schwarze und weiße Nashörner','Rothschild-Giraffen','Flamingos und Pelikane bei günstigen Bedingungen','Löwen, Leoparden, Büffel und Wasserböcke'],faqs:[{q:'Sind Flamingos immer am Lake Nakuru?',a:'Nein. Ihre Zahl verändert sich mit Wasserbedingungen und Nahrungsangebot. Der Park bleibt auch bei weniger Flamingos für Nashörner und Giraffen lohnend.'},{q:'Wie lange sollten wir bleiben?',a:'Ein voller Tag oder eine Übernachtung eignen sich gut in Kombination mit Masai Mara oder anderen Rift-Valley-Zielen.'}]},
    'naivasha-hells-gate':{name:'Lake Naivasha & Hell’s Gate',tagline:'Süßwasser, Vulkanklippen und eines der besten aktiven Abenteuer Kenias',intro:'Lake Naivasha ist ein Süßwassersee im Rift Valley, umgeben von Akazien, Blumenfarmen und Vulkanlandschaften. Der nahe Hell’s Gate National Park ist ungewöhnlich, weil man ausgewählte Bereiche zu Fuß oder mit dem Fahrrad erkunden kann — zwischen hohen Klippen, geothermalen Erscheinungen und Zebra-, Giraffen- und Büffelherden.',history:'Naivasha ist seit Langem Teil der pastoralen und landwirtschaftlichen Landschaft des Rift Valley. Hell’s Gate wurde 1984 zum Nationalpark erklärt und erhielt seinen Namen von einer engen Öffnung in den Klippen.',bestSeason:'Januar–Februar und Juni–Oktober sind beliebt wegen trockenerer Wege und klarerer Aussichten. Die grünen Jahreszeiten können für Landschaften und Vogelbeobachtung spektakulär sein.',wildlifeHighlights:['Zebras, Giraffen und Büffel','Flusspferde im Lake Naivasha','Vogelreiche Süßwasserufer','Radfahren und Wandern zwischen Vulkanklippen'],faqs:[{q:'Kann man in Hell’s Gate wandern?',a:'Ja, in ausgewiesenen Bereichen und mit geeigneter lokaler Begleitung. Es ist einer der zugänglichsten Parks Kenias für aktive Erkundungen.'},{q:'Ist Naivasha für Familien geeignet?',a:'Ja. See, leichte Spaziergänge, Bootsfahrten und Radfahren in Hell’s Gate bringen Abwechslung in eine Familiensafari.'}]},
    'mount-kenya':{name:'Mount Kenya',tagline:'Hochlandwälder, alpine Täler und Afrikas zweithöchster Gipfel',intro:'Der Mount Kenya National Park führt durch Bergwald, Bambus und Moorland zu dramatischen vulkanischen Gipfeln. Die unteren Hänge bieten Lebensraum für Elefanten und Büffel, während die höheren Lagen alpine Vegetation, Felswände und Gletscherspuren zeigen.',history:'Mount Kenya ist ein erloschener Vulkan und ein heiliger Berg in der Kikuyu-Tradition. Nationalpark und Waldreservat schützen seine außergewöhnlichen Ökosysteme; der Berg ist seit 1997 UNESCO-Welterbe.',bestSeason:'Januar–Februar und Juni–September sind wegen oft trockenerer Bedingungen günstig zum Trekking. Bergwetter kann sich jederzeit schnell ändern.',wildlifeHighlights:['Elefanten und Büffel im Waldgebiet','Colobusaffen und andere Waldprimaten','Alpine Pflanzen und Hochlandlandschaften','Vielfältige Bergvogelwelt'],faqs:[{q:'Ist Mount Kenya nur für erfahrene Bergsteiger?',a:'Nein. Wald- und Moorland-Erlebnisse können für Reisende gestaltet werden, die Landschaft und Natur ohne den höchsten Gipfel erleben möchten.'},{q:'Kann man Mount Kenya mit einer Safari kombinieren?',a:'Ja. Mount Kenya passt gut zu Samburu, Ol Pejeta, Lake Nakuru und Masai Mara.'}]},
    serengeti:{name:'Serengeti',tagline:'Endlose Ebenen, Raubtierland und der südliche Teil der Großen Migration',intro:'Der Serengeti National Park ist eine der prägenden Wildtierlandschaften Afrikas: riesige Grasflächen mit Kopjes, Flusskorridoren und Wald. Er ist berühmt für seine Raubtiere und die jährliche Bewegung von Gnus, Zebras und Gazellen durch das Serengeti-Mara-Ökosystem.',history:'Serengeti wurde 1951 zum Nationalpark und später Teil eines größeren Schutzsystems mit der Ngorongoro Conservation Area. Der Name stammt aus einem Maasai-Ausdruck, der meist mit „endlose Ebenen“ übersetzt wird.',bestSeason:'Juni–Oktober ist beliebt für die Trockenzeit und Migrationsaktivität im Norden. Januar–März kann im Süden zur Kalbungszeit ausgezeichnet sein; der genaue Zeitpunkt variiert jedes Jahr.',wildlifeHighlights:['Herden der Großen Migration','Löwen, Geparden und Leoparden','Große Elefanten- und Büffelbestände','Krokodile und Flusspferde in den Flusssystemen'],faqs:[{q:'Ist die Serengeti dasselbe wie die Masai Mara?',a:'Nein. Es sind unterschiedliche Schutzgebiete in Tansania und Kenia, die jedoch ein verbundenes Ökosystem schützen und die jährliche Migration teilen.'},{q:'Wann findet die Migration in der Serengeti statt?',a:'Sie bewegt sich kontinuierlich durch das Ökosystem. Die Kalbung im Süden wird häufig mit Januar–März verbunden, Flussüberquerungen eher mit dem Norden später im Jahr.'}]},
    ngorongoro:{name:'Ngorongoro Crater',tagline:'Eine vulkanische Caldera mit einer der dichtesten Wildtierszenen Afrikas',intro:'Der Ngorongoro Crater ist eine riesige vulkanische Caldera, deren eingeschlossenes Grasland, Wald, See und Feuchtgebiete eine außergewöhnliche Wildtierdichte beherbergen. Die Fahrt hinab fühlt sich wie der Eintritt in ein natürliches Amphitheater an, in dem Löwen und Hyänen durch die Ebenen ziehen.',history:'Der Krater entstand, als ein gewaltiger Vulkan vor etwa zwei bis drei Millionen Jahren kollabierte. Die Ngorongoro Conservation Area wurde 1959 gegründet und verbindet Naturschutz mit pastoralen Gemeinschaften und kulturellem Erbe.',bestSeason:'Juni–Oktober ist eine beliebte Trockenzeit mit klaren Bedingungen und konzentrierter Tierwelt. Januar–März bringt grüne Landschaften und Kalbungsaktivität im weiteren Ökosystem.',wildlifeHighlights:['Hohe Dichte an Löwen und Hyänen','Elefanten und große Büffelherden','Flusspferde in den Kraterfeuchtgebieten','Eine der stärkeren Regionen Nordtansanias für Nashornbeobachtungen'],faqs:[{q:'Kann man im Krater übernachten?',a:'Die meisten Unterkünfte liegen am Kraterrand oder im umliegenden Schutzgebiet, nicht auf dem Kraterboden. Pirschfahrten fahren zu erlaubten Zeiten hinunter.'},{q:'Wie viel Zeit braucht man?',a:'Eine Kraterfahrt kann an einem Tag stattfinden, besonders in Kombination mit Serengeti oder Tarangire.'}]},
    tarangire:{name:'Tarangire',tagline:'Baobabs, riesige Elefantenherden und ein Fluss als Lebensader der Trockenzeit',intro:'Der Tarangire National Park ist für riesige Baobabs, saisonale Feuchtgebiete und einen Fluss bekannt, der in den trockenen Monaten Wildtiere anzieht. Elefantenherden sind charakteristisch, aber auch Giraffen, Zebras, Gnus, Großkatzen und eine außergewöhnliche Vogelwelt lohnen die Reise.',history:'Tarangire wurde 1970 nach Jahren als geschütztes Wildreservat zum Nationalpark. Der Tarangire-Fluss und die umliegenden Wanderwege sind besonders während der Trockenzeit für die ökologische Bedeutung des Parks entscheidend.',bestSeason:'Juni–Oktober ist besonders ergiebig, weil sich Tiere am Tarangire-Fluss und an verbleibenden Wasserstellen sammeln. November–Mai bringt grüneres Gelände und viele Vögel.',wildlifeHighlights:['Große Elefantenherden','Alte Baobab-Landschaften','Löwen, Leoparden und Geparden','Reiche Vogelwelt und saisonale Zugvögel'],faqs:[{q:'Warum Tarangire, wenn wir bereits die Serengeti besuchen?',a:'Tarangire bietet eine eigene Landschaft, riesige Baobabs und starke Elefantenbeobachtungen — ein lohnender Kontrast auf einer Nordtansania-Reise.'},{q:'Eignet sich Tarangire für eine kurze Safari?',a:'Ja. Ein Besuch von einem oder zwei Tagen ab der Region Arusha funktioniert sehr gut.'}]},
    zanzibar:{name:'Zanzibar',tagline:'Swahili-Geschichte, Gewürzinseln und türkisfarbene Strände des Indischen Ozeans',intro:'Zanzibar ist die natürliche Badeverlängerung einer Nordtansania-Safari: Korallenriffe, weiße Strände, Gewürzplantagen und die engen Gassen von Stone Town schaffen nach Tagen im Busch einen völlig anderen Rhythmus.',history:'Zanzibar war ein bedeutendes Handelszentrum des Indischen Ozeans, geprägt von afrikanischen, arabischen, persischen, indischen und europäischen Einflüssen. Stone Town bewahrt diese vielschichtige Swahili-Geschichte und ist UNESCO-Welterbe.',bestSeason:'Juni–Oktober ist eine beliebte Trockenzeit. Dezember–Februar ist ebenfalls warm und meist günstig. April–Mai bringt die langen Regenfälle und weniger Besucher.',wildlifeHighlights:['Delfine und Riffleben','Rote Colobusaffen auf Unguja','Korallengärten und Strände des Indischen Ozeans','Stone Town und Erbe der Gewürzrouten'],faqs:[{q:'Kann Zanzibar mit einer Safari kombiniert werden?',a:'Ja. Zanzibar ist eine der einfachsten Badeverlängerungen nach Serengeti, Ngorongoro oder Tarangire, mit regelmäßigen Flugverbindungen.'},{q:'Ist Zanzibar nur für Strände da?',a:'Nein. Stone Town, Gewürzfarmen, Dhow-Fahrten, Riffe und kulturelle Erlebnisse machen die Insel zu einem eigenständigen Reiseziel.'}]},
    'queen-elizabeth':{name:'Queen Elizabeth National Park',tagline:'Kazinga-Channel-Gewässer, Kraterseen und Ugandas klassische Savannensafari',intro:'Der Queen Elizabeth National Park liegt zwischen Lake Edward und Lake George und verbindet offene Savanne mit Kraterseen, Wald und dem wildreichen Kazinga Channel. Bootsfahrten zeigen Flusspferde, Krokodile und zahlreiche Wasservögel; Pirschfahrten suchen Elefanten, Löwen, Büffel und Uganda-Kobs.',history:'Der Park wurde 1954 gegründet und nach Queen Elizabeth II. benannt. Er liegt im Albertine Rift, einer der artenreichsten Regionen Afrikas.',bestSeason:'Juni–September und Dezember–Februar sind wegen trockenerer Bedingungen und guter Wildbeobachtung beliebt. Die feuchteren Monate können für Landschaften und Vogelbeobachtung hervorragend sein.',wildlifeHighlights:['Baumkletternde Löwen im Ishasha-Gebiet','Flusspferde und Krokodile am Kazinga Channel','Elefanten, Büffel und Uganda-Kob','Außergewöhnliche Vogelvielfalt'],faqs:[{q:'Warum Queen Elizabeth statt Kenia?',a:'Der Park bietet eine andere Albertine-Rift-Landschaft, hervorragende Bootsbeobachtungen und Zugang zu Ugandas Wald- und Primatenzielen.'},{q:'Kann man ihn mit Gorilla-Trekking kombinieren?',a:'Ja. Queen Elizabeth ist eine häufige Station längerer Reisen Richtung Bwindi.'}]},
    bwindi:{name:'Bwindi Impenetrable Forest',tagline:'Uralter Regenwald und eine der außergewöhnlichsten Begegnungen mit Berggorillas',intro:'Bwindi ist ein steiler, uralter Regenwald, der für Gorilla-Trekking bekannt ist. Dichte Vegetation, neblige Bergrücken und außergewöhnliche Artenvielfalt machen den Wald völlig anders als offene Savannenparks. Das Trekking ist anspruchsvoll, aber sehr lohnend.',history:'Bwindi wurde 1991 zum Nationalpark und 1994 zum UNESCO-Welterbe. Naturschutztourismus unterstützt den Schutz der Gorillas und benachbarter Gemeinden.',bestSeason:'Juni–August und Dezember–Februar werden oft bevorzugt, da Wege weniger nass sein können. Gorilla-Trekking findet jedoch ganzjährig statt und Regen ist im Wald immer möglich.',wildlifeHighlights:['Berggorillas','Goldmeerkatzen und andere Primaten in der Umgebung','Endemische Vögel des Albertine Rift','Uralter Bergregenwald'],faqs:[{q:'Ist Gorilla-Trekking körperlich schwierig?',a:'Es kann anstrengend sein. Dauer und Gelände hängen von der Gorilla-Familie und den Bedingungen ab. Reisende sollten auf steile, schlammige Waldwege vorbereitet sein.'},{q:'Wie früh sollten Gorilla-Permits geplant werden?',a:'Die Permits sind begrenzt und sehr gefragt. Sie sollten lange im Voraus über zuständige ugandische Stellen oder einen seriösen Anbieter gesichert werden.'}]},
    'murchison-falls':{name:'Murchison Falls',tagline:'Der Nil wird durch eine Schlucht gepresst und stürzt dann in Ugandas Savanne',intro:'Der Murchison Falls National Park ist Ugandas größtes Schutzgebiet. Der Nil zwängt sich durch eine enge Schlucht, bevor er in kraftvollen Fällen hinabstürzt. Bootsfahrten, Flussuferwildtiere und weite Savannenebenen ergeben eine der markantesten Landschaften Ostafrikas.',history:'Der Park wurde 1952 ausgewiesen und ist Teil einer größeren geschützten Landschaft entlang des Victoria Nile. Die Fälle und der Flusskorridor sind seit Generationen prägende Wahrzeichen Nordugandas.',bestSeason:'Juni–September und Dezember–Februar sind beliebte Trockenzeiten. Wasserstände und Vegetation verändern sich im Jahresverlauf und damit auch das Erscheinungsbild der Fälle.',wildlifeHighlights:['Flusspferde und Nilkrokodile','Elefanten, Giraffen und Büffel','Löwen und andere Savannenräuber','Nilsafari per Boot und Aussichtspunkt der Murchison Falls'],faqs:[{q:'Geht es bei Murchison Falls nur um den Wasserfall?',a:'Nein. Pirschfahrten und die Nilsafari sind Hauptattraktionen, mit guten Chancen auf Elefanten, Giraffen, Büffel, Flusspferde und Krokodile.'},{q:'Wie passt Murchison Falls in eine Uganda-Reise?',a:'Der Park lässt sich mit Schimpansen- oder Gorilla-Erlebnissen zu einer Reise aus Savanne, Fluss und Regenwald verbinden.'}]},
    akagera:{name:'Akagera',tagline:'Seen, Papyrus-Feuchtgebiete und ein sich erholendes Big-Five-Ökosystem in Rwanda',intro:'Der Akagera National Park ist Rwandas Savannen-Gegenstück zu den Bergwäldern. Hügellandschaften, Seen, Papyrus-Feuchtgebiete und Wald beherbergen Elefanten, Büffel, Giraffen, Zebras, Antilopen und eine wachsende Raubtierpopulation. Eine Bootsfahrt auf Lake Ihema eröffnet eine andere Perspektive.',history:'Akagera wurde 1934 gegründet und erlitt später während Konflikten und Vertreibungen schwere Wildtierverluste. Wiederherstellungs- und Wiederansiedlungsprogramme haben das Ökosystem gestärkt, darunter die Rückkehr von Löwen und Spitzmaulnashörnern.',bestSeason:'Juni–September ist meist trockener und gut für Pirschfahrten. März–Mai ist feuchter und grüner; Oktober–Februar kann für Vogelbeobachtung und üppige Landschaften sehr gut sein.',wildlifeHighlights:['Big-Five-Wiederherstellungslandschaft','Flusspferde und Krokodile am Lake Ihema','Giraffen, Zebras, Elefanten und Büffel','Papyrus-Feuchtgebiete und reiche Vogelwelt'],faqs:[{q:'Kann Akagera mit Gorilla-Trekking kombiniert werden?',a:'Ja. Eine Rwanda-Reise kann Akagera-Savanne mit Gorillas oder Goldmeerkatzen im Volcanoes National Park verbinden.'},{q:'Eignet sich Akagera für eine kurze Safari?',a:'Ja. Das kompakte Straßennetz und die Kombination aus See und Savanne machen zwei oder drei Tage praktisch.'}]},
  },
  ar: {
    samburu:{name:'Samburu',tagline:'جمال الأراضي الجافة والأنواع النادرة في الشمال ونهر إواسو نغيرو',intro:'تقدم محمية سامبورو الوطنية تبايناً واضحاً مع متنزهات جنوب كينيا الأكثر رطوبة؛ تلتقي التلال الصخرية ونخيل الدوم والسهول الذهبية حول نهر إواسو نغيرو. وتشتهر بـ«الخمسة المميزين في سامبورو» إلى جانب الأسود والنمور والفيلة والكلاب البرية.',history:'أصبحت سامبورو محمية محمية في عام 1985. وظلت المنطقة موطناً لمجتمعات سامبورو الرعوية التي ترتبط معرفتها بالمياه الموسمية والمراعي والحياة البرية ارتباطاً وثيقاً بالنظام البيئي.',bestSeason:'يونيو–أكتوبر ويناير–فبراير فترتان جافتان شائعتان، حيث تتركز الحيوانات قرب النهر. أما المواسم الخضراء فتقدم مناظر رائعة وطيوراً مهاجرة.',wildlifeHighlights:['الخمسة المميزون في سامبورو','الفيلة على طول نهر إواسو نغيرو','النمور والأسود والكلاب البرية الأفريقية','الزرافات الشبكية وحمار وحشي غريفي'],faqs:[{q:'ما الذي يميز سامبورو عن ماساي مارا؟',a:'تتميز سامبورو بمناظر شمالية أكثر جفافاً وبأنواع نادرة في جنوب كينيا، لذلك فهي مكملة ممتازة لمارا.'},{q:'هل يمكن الجمع بين سامبورو والمتنزهات الأخرى؟',a:'نعم. يمكن جمعها بشكل ممتاز مع أول بيجيتا أو جبل كينيا أو بحيرة ناكورو.'}]},
    'lake-nakuru':{name:'Lake Nakuru',tagline:'منحدرات الوادي المتصدع ووحيد القرن وبحيرة تشتهر بطيور الفلامنغو',intro:'يقع متنزه بحيرة ناكورو الوطني حول بحيرة قلوية ضحلة في الوادي المتصدع العظيم. تجمع المراعي والمنحدرات الصخرية وغابات الأكاسيا والأراضي الرطبة بين تنوع كبير في منطقة مدمجة، خاصة لوحيد القرن الأسود والأبيض وزرافات روثتشايلد والطيور المائية.',history:'أصبحت منطقة بحيرة ناكورو متنزهاً وطنياً في عام 1968. اشتهرت البحيرة عالمياً بتجمعات الفلامنغو الكبيرة، ثم عززت أعمال الحماية أهميتها كملاذ لوحيد القرن والأنواع المهددة.',bestSeason:'يونيو–أكتوبر ويناير–فبراير فترتان جافتان موثوقتان لمشاهدة الحياة البرية. ويتغير عدد الفلامنغو وفق مستوى المياه وظروف البحيرة وتوفر الغذاء.',wildlifeHighlights:['وحيد القرن الأسود والأبيض','زرافات روثتشايلد','الفلامنغو والبجع عندما تكون الظروف مناسبة','الأسود والنمور والجاموس والواترباك'],faqs:[{q:'هل الفلامنغو موجود دائماً في بحيرة ناكورو؟',a:'لا. يتغير عددها مع ظروف المياه والغذاء. وتظل الحديقة ممتازة لوحيد القرن والزرافات والحيوانات الأخرى.'},{q:'كم من الوقت نحتاج هنا؟',a:'يوم كامل أو ليلة واحدة مناسبان عند الجمع بين ناكورو وماساي مارا أو وجهات أخرى في الوادي المتصدع.'}]},
    'naivasha-hells-gate':{name:'Lake Naivasha & Hell’s Gate',tagline:'مياه عذبة ومنحدرات بركانية وواحدة من أفضل مغامرات كينيا النشطة',intro:'بحيرة نيفاشا بحيرة عذبة في الوادي المتصدع تحيط بها أشجار الأكاسيا ومزارع الزهور والمناظر البركانية. أما متنزه هيلز غيت القريب فيتيح في مناطق محددة الاستكشاف سيراً أو بالدراجة بين المنحدرات العالية والظواهر الحرارية الأرضية وحيوانات الحمار الوحشي والزراف والجاموس.',history:'كانت نيفاشا منذ زمن طويل جزءاً من المشهد الرعوي والزراعي للوادي المتصدع. وأعلن هيلز غيت متنزهاً وطنياً في عام 1984 وسمي نسبة إلى فتحة ضيقة بين المنحدرات.',bestSeason:'يناير–فبراير ويونيو–أكتوبر فترات مفضلة للممرات الأكثر جفافاً والرؤية الأوضح. ويمكن أن تكون المواسم الخضراء رائعة للمناظر والطيور.',wildlifeHighlights:['الحمار الوحشي والزراف والجاموس','أفراس النهر في بحيرة نيفاشا','ضفاف غنية بالطيور','ركوب الدراجات والمشي بين المنحدرات البركانية'],faqs:[{q:'هل يمكننا المشي في هيلز غيت؟',a:'نعم، في المناطق المخصصة ومع الإرشاد المحلي المناسب. وهو من أكثر متنزهات كينيا ملاءمة للاستكشاف النشط.'},{q:'هل نيفاشا مناسبة للعائلات؟',a:'نعم. البحيرة والمشي السهل ورحلات القوارب وركوب الدراجات تضيف تنوعاً إلى رحلات السفاري العائلية.'}]},
    'mount-kenya':{name:'Mount Kenya',tagline:'غابات المرتفعات والوديان الألبية وثاني أعلى قمة في أفريقيا',intro:'يمتد متنزه جبل كينيا الوطني عبر الغابات الجبلية والخيزران والمروج المرتفعة نحو قمم بركانية مذهلة. وتوفر المنحدرات السفلى موطناً للفيلة والجاموس، بينما تكشف الارتفاعات الأعلى عن نباتات ألبية وجدران صخرية وآثار جليدية.',history:'جبل كينيا بركان خامد قديم وجبل مقدس في تقاليد الكيكويو. تحمي الحديقة الوطنية ومحمية الغابات المحيطة أنظمته البيئية الاستثنائية، وأدرج الجبل ضمن التراث العالمي لليونسكو عام 1997.',bestSeason:'يناير–فبراير ويونيو–سبتمبر فترات مناسبة عادةً للرحلات بسبب الجفاف النسبي. ويمكن أن يتغير طقس الجبل بسرعة في أي وقت.',wildlifeHighlights:['الفيلة والجاموس في منطقة الغابات','قرود الكولوبوس وغيرها من الرئيسيات','نباتات ألبية ومناظر المرتفعات','تنوع غني من طيور الجبال'],faqs:[{q:'هل جبل كينيا مخصص للمتسلقين المحترفين فقط؟',a:'لا. يمكن تصميم تجارب في الغابات والمروج للاستمتاع بالطبيعة والمناظر دون محاولة الوصول إلى أعلى قمة.'},{q:'هل يمكن دمجه مع رحلة سفاري؟',a:'نعم. يجتمع جبل كينيا بشكل طبيعي مع سامبورو وأول بيجيتا وبحيرة ناكورو وماساي مارا.'}]},
    serengeti:{name:'Serengeti',tagline:'سهول لا تنتهي وأرض المفترسات والقسم الجنوبي من الهجرة الكبرى',intro:'يعد متنزه سيرينغيتي الوطني من أشهر مناظر الحياة البرية في أفريقيا: سهول عشبية واسعة تتخللها صخور الكوبجي وممرات الأنهار والغابات. ويشتهر بكثافة المفترسات المقيمة وبحركة قطعان الحيوانات السنوية عبر نظام سيرينغيتي–مارا البيئي.',history:'أصبح سيرينغيتي متنزهاً وطنياً في عام 1951، ثم أصبح جزءاً من نظام حماية أوسع مع منطقة نجورونجورو. ويأتي الاسم من تعبير ماساي يترجم عادةً إلى «السهول التي لا تنتهي».',bestSeason:'يونيو–أكتوبر فترة شائعة للمشاهدة في موسم الجفاف ونشاط الهجرة شمالاً. ويمكن أن يكون يناير–مارس ممتازاً في الجنوب خلال موسم الولادات، بينما تختلف المواعيد كل عام.',wildlifeHighlights:['قطعان الهجرة الكبرى','الأسود والفهود والفهود الصيادة','أعداد كبيرة من الفيلة والجاموس','التماسيح وأفراس النهر في الأنهار'],faqs:[{q:'هل سيرينغيتي هو نفسه ماساي مارا؟',a:'لا. هما منطقتان محميتان مختلفتان في تنزانيا وكينيا، لكنهما جزء من نظام بيئي متصل ويشتركان في الهجرة السنوية.'},{q:'متى تحدث الهجرة في سيرينغيتي؟',a:'تتحرك باستمرار عبر النظام البيئي. ترتبط الولادات في الجنوب عادةً بين يناير ومارس، بينما ترتبط عبورات الأنهار بالقطاع الشمالي في وقت لاحق من السنة.'}]},
    ngorongoro:{name:'Ngorongoro Crater',tagline:'فوهة بركانية تضم واحدة من أكثر مشاهد الحياة البرية كثافة في أفريقيا',intro:'فوهة نجورونجورو كالديرا بركانية ضخمة تضم مراعي وغابات وبحيرة وأراضي رطبة غنية بالحياة البرية. ويشعر الزائر عند النزول إلى الفوهة وكأنه يدخل مسرحاً طبيعياً تتحرك فيه الأسود والضباع والحيوانات العاشبة بين الماء والمراعي.',history:'تشكلت الفوهة بعد انهيار بركان هائل قبل نحو مليونين إلى ثلاثة ملايين سنة. وأُنشئت منطقة نجورونجورو للحفظ عام 1959 وتجمع بين حماية الحياة البرية والمجتمعات الرعوية والتراث الثقافي.',bestSeason:'يونيو–أكتوبر فترة جافة شائعة للرؤية الواضحة وتركيز الحيوانات. ويقدم يناير–مارس مناظر خضراء ونشاط الولادات في النظام البيئي الأوسع.',wildlifeHighlights:['كثافة عالية من الأسود والضباع','الفيلة وقطعان الجاموس الكبيرة','أفراس النهر في الأراضي الرطبة للفوهة','من أقوى مناطق شمال تنزانيا لمشاهدة وحيد القرن'],faqs:[{q:'هل يمكن المبيت داخل الفوهة؟',a:'تقع معظم أماكن الإقامة على حافة الفوهة أو في منطقة الحماية المحيطة، وليس في القاع. وتنزل رحلات السفاري إلى الفوهة خلال الساعات المسموح بها.'},{q:'كم من الوقت نحتاج؟',a:'يمكن أن تستغرق رحلة الفوهة يوماً واحداً، خاصة عند دمجها مع سيرينغيتي أو ترانغيري.'}]},
    tarangire:{name:'Tarangire',tagline:'أشجار الباوباب وقطعان الفيلة الكبيرة ونهر يصبح شرياناً للحياة في موسم الجفاف',intro:'يشتهر متنزه ترانغيري الوطني بأشجار الباوباب العملاقة والأراضي الرطبة الموسمية والنهر الذي يجذب الحيوانات خلال الأشهر الجافة. الفيلة مشهد مميز، لكن الحديقة تقدم أيضاً الزرافات والحمر الوحشية والنو والقطط الكبيرة وطيوراً متنوعة.',history:'أصبح ترانغيري متنزهاً وطنياً في عام 1970 بعد سنوات كمحمية صيد محمية. ويظل نهر ترانغيري ومسارات الهجرة المحيطة به محور أهميته البيئية، خاصة خلال موسم الجفاف في تنزانيا.',bestSeason:'يونيو–أكتوبر منتج بشكل خاص لأن الحيوانات تتجمع حول نهر ترانغيري ومصادر المياه المتبقية. ويجلب نوفمبر–مايو مناظر أكثر خضرة وكثيراً من الطيور.',wildlifeHighlights:['قطعان الفيلة الكبيرة','مناظر الباوباب القديمة','الأسود والنمور والفهود','حياة طيور غنية وأنواع مهاجرة موسمية'],faqs:[{q:'لماذا نختار ترانغيري إذا كنا سنزور سيرينغيتي أيضاً؟',a:'لترانغيري منظر مختلف وباوباب ضخم ومشاهدة قوية للفيلة، مما يجعله تبايناً رائعاً في رحلة شمال تنزانيا.'},{q:'هل ترانغيري مناسب لسفاري قصيرة؟',a:'نعم. يمكن زيارته جيداً خلال يوم أو يومين من منطقة أروشا.'}]},
    zanzibar:{name:'Zanzibar',tagline:'تاريخ سواحلي وجزر التوابل وشواطئ فيروزية على المحيط الهندي',intro:'زنجبار امتداد شاطئي طبيعي لرحلة سفاري في شمال تنزانيا: الشعاب المرجانية والشواطئ البيضاء ومزارع التوابل وأزقة ستون تاون تمنح المسافر إيقاعاً مختلفاً تماماً بعد أيام السفاري.',history:'كانت زنجبار مركزاً مهماً للتجارة في المحيط الهندي وتأثرت بثقافات أفريقية وعربية وفارسية وهندية وأوروبية. وتحفظ ستون تاون هذه الطبقات من التاريخ السواحلي وهي مدرجة ضمن التراث العالمي لليونسكو.',bestSeason:'يونيو–أكتوبر فترة جافة شائعة. كما أن ديسمبر–فبراير دافئ ومناسب عموماً. ويجلب أبريل–مايو الأمطار الطويلة وعدداً أقل من الزوار.',wildlifeHighlights:['الدلافين وحياة الشعاب','قرود الكولوبوس الحمراء في أونغوجا','حدائق مرجانية وشواطئ المحيط الهندي','ستون تاون وتراث طرق التوابل'],faqs:[{q:'هل يمكن دمج زنجبار مع سفاري؟',a:'نعم. زنجبار من أسهل الإضافات الشاطئية بعد سيرينغيتي أو نجورونجورو أو ترانغيري بفضل الرحلات الجوية المنتظمة.'},{q:'هل زنجبار مجرد شواطئ؟',a:'لا. ستون تاون ومزارع التوابل ورحلات الداو والشعاب والتجارب الثقافية تجعلها وجهة متكاملة.'}]},
    'queen-elizabeth':{name:'Queen Elizabeth National Park',tagline:'مياه قناة كازنغا وبحيرات الفوهات وسفاري السافانا الكلاسيكية في أوغندا',intro:'يمتد متنزه كوين إليزابيث الوطني بين بحيرتي إدوارد وجورج، ويجمع السافانا المفتوحة وبحيرات الفوهات والغابات وقناة كازنغا الغنية بالحياة البرية. تكشف رحلات القوارب أفراس النهر والتماسيح وأعداداً كبيرة من الطيور المائية، بينما تبحث رحلات السفاري عن الفيلة والأسود والجاموس والكوب الأوغندي.',history:'أُنشئ المتنزه عام 1954 وسمي باسم الملكة إليزابيث الثانية. يقع في صدع ألبرتين، إحدى أكثر مناطق أفريقيا تنوعاً بيولوجياً.',bestSeason:'يونيو–سبتمبر وديسمبر–فبراير فترتان شائعتان للظروف الأكثر جفافاً ومشاهدة الحيوانات. ويمكن أن تكون الأشهر الرطبة رائعة للمناظر والطيور.',wildlifeHighlights:['الأسود المتسلقة للأشجار في منطقة إيشاشا','أفراس النهر والتماسيح في قناة كازنغا','الفيلة والجاموس والكوب الأوغندي','تنوع استثنائي للطيور'],faqs:[{q:'لماذا نزور كوين إليزابيث بدلاً من كينيا؟',a:'تقدم مناظر مختلفة لصدع ألبرتين وتجارب ممتازة بالقوارب والوصول إلى وجهات الغابات والرئيسيات في أوغندا.'},{q:'هل يمكن دمجها مع رحلة الغوريلا؟',a:'نعم. كوين إليزابيث محطة شائعة في الرحلات الطويلة المتجهة إلى بويندي.'}]},
    bwindi:{name:'Bwindi Impenetrable Forest',tagline:'غابة مطيرة قديمة وواحدة من أروع لقاءات الغوريلا الجبلية في العالم',intro:'بويندي غابة مطيرة جبلية قديمة تشتهر برحلات تتبع الغوريلا الجبلية. الغطاء النباتي الكثيف والقمم الضبابية والتنوع البيولوجي الاستثنائي يجعلها مختلفة تماماً عن حدائق السافانا. الرحلة شاقة لكنها مجزية للغاية.',history:'أعلنت بويندي متنزهاً وطنياً عام 1991 وأدرجت ضمن التراث العالمي لليونسكو عام 1994. ويساعد سياحة الحفظ في حماية الغوريلا والمجتمعات المجاورة.',bestSeason:'يونيو–أغسطس وديسمبر–فبراير فترات مفضلة غالباً لأن المسارات قد تكون أقل رطوبة، لكن التتبع متاح طوال العام والمطر ممكن دائماً.',wildlifeHighlights:['الغوريلا الجبلية','القرود الذهبية ورئيسيات أخرى قريبة','طيور متوطنة في صدع ألبرتين','غابة جبلية مطيرة قديمة'],faqs:[{q:'هل تتبع الغوريلا صعب بدنياً؟',a:'قد يكون كذلك. تختلف مدة الرحلة والتضاريس حسب مجموعة الغوريلا والظروف. يجب الاستعداد لمسارات غابية شديدة الانحدار وموحلة.'},{q:'متى يجب التخطيط لتصاريح الغوريلا؟',a:'التصاريح محدودة ومطلوبة بشدة، لذلك ينبغي تأمينها قبل السفر بوقت طويل عبر الجهات الأوغندية المختصة أو مشغل موثوق.'}]},
    'murchison-falls':{name:'Murchison Falls',tagline:'يضيق النيل داخل وادٍ قبل أن يندفع بقوة إلى سافانا أوغندا',intro:'متنزه مورشيسون فولز الوطني هو أكبر منطقة محمية في أوغندا. يمر النيل عبر مضيق ضيق قبل أن يسقط في شلالات قوية. تجمع رحلات القوارب والحياة البرية على النهر وسهول السافانا الواسعة بين عناصر واحدة من أكثر مناظر شرق أفريقيا تميزاً.',history:'أعلن المتنزه عام 1952 ويقع ضمن مشهد محمي أوسع على طول نهر النيل الفيكتوري. وظلت الشلالات وممر النهر معالم رئيسية لشمال أوغندا لأجيال.',bestSeason:'يونيو–سبتمبر وديسمبر–فبراير فترات جافة شائعة. وتتغير مستويات المياه والنباتات خلال العام، ما يغير مظهر الشلالات والنهر.',wildlifeHighlights:['أفراس النهر وتماسيح النيل','الفيلة والزرافات والجاموس','الأسود ومفترسات السافانا الأخرى','رحلة قارب في النيل وإطلالة على الشلالات'],faqs:[{q:'هل مورشيسون فولز مجرد شلال؟',a:'لا. رحلات السفاري ورحلة القارب في النيل من أهم التجارب، مع فرص جيدة لرؤية الفيلة والزرافات والجاموس وأفراس النهر والتماسيح.'},{q:'كيف يمكن دمجها في رحلة أوغندا؟',a:'يمكن دمجها مع تجارب الشمبانزي أو الغوريلا لرحلة تجمع السافانا والنهر والغابات المطيرة.'}]},
    akagera:{name:'Akagera',tagline:'بحيرات وأراضي بَردي رطبة ونظام بيئي للخمسة الكبار يتعافى في رواندا',intro:'متنزه أكاجيرا الوطني هو نظير السافانا للغابات الجبلية في رواندا. تدعم السهول المتدرجة والبحيرات والأراضي الرطبة والغابات الفيلة والجاموس والزرافات والحمر الوحشية والظباء ومجموعة متزايدة من المفترسات. وتقدم رحلة قارب في بحيرة إيهِما منظوراً مختلفاً.',history:'أُنشئت أكاجيرا عام 1934 ثم فقدت أعداداً كبيرة من الحيوانات خلال فترات الصراع والنزوح. ساعدت برامج الاستعادة وإعادة التوطين على بناء النظام البيئي، بما في ذلك عودة الأسود ووحيد القرن الأسود.',bestSeason:'يونيو–سبتمبر أكثر جفافاً عموماً ومناسب لمشاهدة الحيوانات. مارس–مايو أكثر رطوبة وخضرة، بينما يمكن أن يكون أكتوبر–فبراير ممتازاً للطيور والمناظر الخصبة.',wildlifeHighlights:['منطقة تعافي للخمسة الكبار','أفراس النهر والتماسيح في بحيرة إيهِما','الزرافات والحمر الوحشية والفيلة والجاموس','أراضي البردي الرطبة وحياة طيور غنية'],faqs:[{q:'هل يمكن دمج أكاجيرا مع رحلات الغوريلا؟',a:'نعم. يمكن لرحلة رواندا أن تجمع سافانا أكاجيرا مع الغوريلا أو القرود الذهبية في متنزه البراكين الوطني.'},{q:'هل أكاجيرا مناسبة لسفاري قصيرة؟',a:'نعم. شبكة الطرق المدمجة ومزيج البحيرة والسافانا يجعلان يومين أو ثلاثة أيام خياراً عملياً.'}]},
  },
  zh: {
    samburu:{name:'Samburu',tagline:'干旱之地的壮丽景色、北方珍稀物种与埃瓦索·恩吉罗河',intro:'桑布鲁国家保护区与肯尼亚南部较湿润的公园形成鲜明对比：岩石丘陵、杜姆棕榈和金色平原环绕埃瓦索·恩吉罗河。这里以“桑布鲁特别五大”闻名，包括格氏斑马、网纹长颈鹿、长颈羚、索马里鸵鸟和东非剑羚，同时也能看到狮子、豹、大象和非洲野犬。',history:'桑布鲁于1985年成为受保护的野生动物保护区。这里长期是桑布鲁牧民社区的家园，他们对季节性水源、牧场和野生动物的知识与生态系统紧密相连。',bestSeason:'6月至10月以及1月至2月是受欢迎的旱季时段，动物会集中在埃瓦索·恩吉罗河附近。绿色季节则带来壮观景色和迁徙鸟类。',wildlifeHighlights:['桑布鲁特别五大','埃瓦索·恩吉罗河畔的大象','豹、狮子和非洲野犬','网纹长颈鹿与格氏斑马'],faqs:[{q:'桑布鲁与马赛马拉有什么不同？',a:'桑布鲁拥有更干燥的北方景观和南部肯尼亚少见的物种，是马赛马拉很好的补充目的地。'},{q:'桑布鲁可以与其他公园结合吗？',a:'可以。它特别适合与奥佩杰塔、肯尼亚山或纳库鲁湖组成更长的肯尼亚线路。'}]},
    'lake-nakuru':{name:'Lake Nakuru',tagline:'裂谷悬崖、犀牛与以火烈鸟闻名的湖泊',intro:'纳库鲁湖国家公园环绕大裂谷中的浅层碱性湖泊。草原、岩石悬崖、金合欢林和湿地共同构成紧凑而丰富的野生动物区域，尤其适合观察黑白犀牛、罗斯柴尔德长颈鹿和水鸟。',history:'纳库鲁湖地区于1968年成为国家公园。湖泊曾因巨大的火烈鸟群而闻名世界，后续保护工作又使这里成为重要的犀牛保护区。',bestSeason:'6月至10月以及1月至2月通常较干燥，适合观赏野生动物。火烈鸟数量会随水位、湖泊条件和食物供应变化。',wildlifeHighlights:['黑犀牛和白犀牛','罗斯柴尔德长颈鹿','条件合适时的火烈鸟和鹈鹕','狮子、豹、水牛和水羚'],faqs:[{q:'纳库鲁湖全年都有火烈鸟吗？',a:'不是。数量会随水况和食物供应变化。即使火烈鸟较少，这里仍非常适合观察犀牛、长颈鹿和其他野生动物。'},{q:'这里需要停留多久？',a:'完整一天或一晚非常适合，尤其是与马赛马拉或其他大裂谷目的地组合时。'}]},
    'naivasha-hells-gate':{name:'Lake Naivasha & Hell’s Gate',tagline:'淡水、火山峭壁与肯尼亚最精彩的主动探险体验之一',intro:'奈瓦沙湖是大裂谷中的淡水湖，周围有金合欢林、花卉农场和火山景观。附近的地狱之门国家公园很特别，在指定区域可以徒步或骑自行车穿越高耸悬崖、地热景观以及斑马、长颈鹿和水牛出没的平原。',history:'奈瓦沙长期属于大裂谷的牧业和农业景观。地狱之门于1984年被列为国家公园，名称来自悬崖间的一处狭窄缺口。',bestSeason:'1月至2月以及6月至10月较受欢迎，步道通常更干燥、景色更清晰。绿色季节的景观和鸟类也非常精彩。',wildlifeHighlights:['斑马、长颈鹿和水牛','奈瓦沙湖中的河马','鸟类丰富的淡水湖岸','火山峭壁间的骑行与徒步'],faqs:[{q:'可以在地狱之门徒步吗？',a:'可以，在指定区域并配合适当的当地向导。这里是肯尼亚最适合主动探索的公园之一。'},{q:'奈瓦沙适合家庭旅行吗？',a:'适合。湖泊、轻松步道、乘船和地狱之门骑行可以让家庭Safari更加丰富。'}]},
    'mount-kenya':{name:'Mount Kenya',tagline:'高山森林、阿尔卑斯山谷与非洲第二高峰',intro:'肯尼亚山国家公园从山地森林、竹林和高山荒原一路延伸至壮观的火山山峰。较低的山坡是大象和水牛的栖息地，更高处则可看到高山植物、岩壁和冰川遗迹。',history:'肯尼亚山是一座古老的死火山，也是基库尤传统中的圣山。国家公园及周围森林保护区保护着独特生态系统，肯尼亚山于1997年被列入联合国教科文组织世界遗产。',bestSeason:'1月至2月和6月至9月通常更适合徒步，因为天气较干燥。山地天气全年都可能迅速变化。',wildlifeHighlights:['森林中的大象和水牛','疣猴及其他森林灵长类','高山植物与高海拔景观','丰富的山地鸟类'],faqs:[{q:'肯尼亚山只适合专业登山者吗？',a:'不是。可以设计森林和高山荒原体验，让游客欣赏自然和景色而无需挑战最高峰。'},{q:'可以与Safari结合吗？',a:'可以。肯尼亚山很适合与桑布鲁、奥佩杰塔、纳库鲁湖和马赛马拉组合。'}]},
    serengeti:{name:'Serengeti',tagline:'无尽平原、捕食者王国与大迁徙南部舞台',intro:'塞伦盖蒂国家公园是非洲最具代表性的野生动物景观之一：广阔草原点缀着岩丘、河流走廊和林地。这里以大量常驻捕食者以及角马、斑马和瞪羚在塞伦盖蒂—马赛马拉生态系统中的年度移动而闻名。',history:'塞伦盖蒂于1951年成为国家公园，后来与恩戈罗恩戈罗保护区共同组成更大的保护体系。“Serengeti”一词源自马赛语，通常译为“无尽平原”。',bestSeason:'6月至10月适合旱季Safari和北部迁徙活动。1月至3月南部可能是产仔的精彩时期，但迁徙时间每年都会变化。',wildlifeHighlights:['大迁徙兽群','狮子、猎豹和豹','数量众多的大象与水牛','河流中的鳄鱼和河马'],faqs:[{q:'塞伦盖蒂和马赛马拉是同一个地方吗？',a:'不是。它们分别位于坦桑尼亚和肯尼亚，但属于相连的生态系统，共同承载年度迁徙。'},{q:'塞伦盖蒂什么时候发生大迁徙？',a:'迁徙会持续移动。南部产仔通常在1月至3月，河流穿越则更多发生在之后的北部地区。'}]},
    ngorongoro:{name:'Ngorongoro Crater',tagline:'火山口中的非洲高密度野生动物奇观',intro:'恩戈罗恩戈罗火山口是一座巨大的火山破火山口，封闭的草原、林地、湖泊和湿地拥有极高的野生动物密度。进入火山口仿佛走进天然圆形剧场，狮子和鬣狗穿行于平原，大型食草动物在水源和牧草之间移动。',history:'火山口形成于约两三百万年前一座巨大火山坍塌之后。恩戈罗恩戈罗保护区成立于1959年，将野生动物保护、牧民社区和文化遗产结合管理。',bestSeason:'6月至10月是受欢迎的旱季窗口，天气清晰且动物更集中。1月至3月景色更绿，并可在更广泛的生态系统中看到产仔活动。',wildlifeHighlights:['高密度狮子与鬣狗','大象和大型水牛群','火山口湿地中的河马','坦桑尼亚北部较佳的犀牛观察区域之一'],faqs:[{q:'可以住在火山口里面吗？',a:'大多数住宿位于火山口边缘或周围保护区，而不是火山口底部。Safari车辆会在允许的时间下到火山口。'},{q:'需要多长时间？',a:'火山口Safari可以安排为一天，尤其适合与塞伦盖蒂或塔兰吉雷组合。'}]},
    tarangire:{name:'Tarangire',tagline:'猴面包树、大象群与旱季生命线般的河流',intro:'塔兰吉雷国家公园以巨大的猴面包树、季节性湿地以及旱季吸引野生动物的河流闻名。大象群是标志性景观，同时还能看到长颈鹿、斑马、角马、大型猫科动物和丰富鸟类。',history:'塔兰吉雷于1970年成为国家公园，此前多年为受保护的野生动物保护区。塔兰吉雷河及周围迁徙路线对公园生态意义重大，尤其是在坦桑尼亚旱季。',bestSeason:'6月至10月尤其适合观赏，因为动物会聚集在塔兰吉雷河及剩余水源附近。11月至5月景色更绿，鸟类也更多。',wildlifeHighlights:['大型象群','古老的猴面包树景观','狮子、豹和猎豹','丰富鸟类与季节性迁徙物种'],faqs:[{q:'如果已经去塞伦盖蒂，为什么还要选择塔兰吉雷？',a:'塔兰吉雷拥有不同的景观、巨大的猴面包树和出色的大象观察，是北坦桑尼亚线路中的精彩对比。'},{q:'塔兰吉雷适合短途Safari吗？',a:'适合。从阿鲁沙地区出发，一到两天的行程非常合适。'}]},
    zanzibar:{name:'Zanzibar',tagline:'斯瓦希里历史、香料岛与印度洋碧蓝海滩',intro:'桑给巴尔是北坦桑尼亚Safari之后自然的海滩延伸：珊瑚礁、白色沙滩、香料种植园以及石头城狭窄街巷，让游客从丛林Safari切换到完全不同的海岛节奏。',history:'桑给巴尔曾是印度洋重要贸易中心，受到非洲、阿拉伯、波斯、印度和欧洲文化影响。石头城保留了多层次的斯瓦希里历史，并被列入联合国教科文组织世界遗产。',bestSeason:'6月至10月是受欢迎的旱季。12月至2月也温暖且通常适宜。4月至5月为长雨季，游客较少。',wildlifeHighlights:['海豚和珊瑚礁生态','Unguja岛的红疣猴','珊瑚花园与印度洋海滩','石头城与香料贸易历史'],faqs:[{q:'桑给巴尔可以与Safari结合吗？',a:'可以。塞伦盖蒂、恩戈罗恩戈罗或塔兰吉雷之后前往桑给巴尔非常方便，有定期航班连接。'},{q:'桑给巴尔只有海滩吗？',a:'不是。石头城、香料农场、三角帆船、珊瑚礁和文化体验使它成为完整的旅行目的地。'}]},
    'queen-elizabeth':{name:'Queen Elizabeth National Park',tagline:'卡津加水道、火山口湖与乌干达经典草原Safari',intro:'伊丽莎白女王国家公园位于爱德华湖与乔治湖之间，结合开放草原、火山口湖、林地以及野生动物丰富的卡津加水道。乘船可以看到河马、鳄鱼和大量水鸟，陆地Safari则寻找大象、狮子、水牛和乌干达牛羚。',history:'公园于1954年建立，并以伊丽莎白二世女王命名。这里位于阿尔伯丁裂谷，是非洲生物多样性最丰富的地区之一。',bestSeason:'6月至9月和12月至2月较受欢迎，天气更干燥、观兽条件较好。湿季则适合欣赏景观和鸟类。',wildlifeHighlights:['伊沙沙地区的爬树狮','卡津加水道的河马和鳄鱼','大象、水牛和乌干达牛羚','极其丰富的鸟类'],faqs:[{q:'为什么选择伊丽莎白女王国家公园而不是肯尼亚？',a:'这里拥有独特的阿尔伯丁裂谷景观、精彩的水上观兽体验，并方便前往乌干达的森林和灵长类动物目的地。'},{q:'可以与大猩猩徒步结合吗？',a:'可以。它是前往布恩迪的长线乌干达旅行中常见的一站。'}]},
    bwindi:{name:'Bwindi Impenetrable Forest',tagline:'古老雨林与世界上最难忘的山地大猩猩邂逅之一',intro:'布恩迪是一片陡峭的古老雨林，以山地大猩猩徒步闻名。茂密植被、雾气缭绕的山脊和丰富生物多样性使这里与开放草原公园完全不同。徒步具有挑战性，但体验非常值得。',history:'布恩迪于1991年成为国家公园，并于1994年列入联合国教科文组织世界遗产。保护旅游为大猩猩保护和邻近社区提供重要支持。',bestSeason:'6月至8月和12月至2月通常较受欢迎，因为步道可能没那么湿，但大猩猩徒步全年进行，雨林中任何时候都有可能下雨。',wildlifeHighlights:['山地大猩猩','附近的金丝猴及其他灵长类','阿尔伯丁裂谷特有鸟类','古老山地雨林'],faqs:[{q:'大猩猩徒步体力要求高吗？',a:'可能较高。徒步时间和地形取决于大猩猩家庭和当天条件，需要准备应对陡峭、泥泞的森林步道。'},{q:'大猩猩许可证需要提前多久计划？',a:'许可证数量有限且需求很高，应通过相关乌干达机构或可靠运营商提前较长时间安排。'}]},
    'murchison-falls':{name:'Murchison Falls',tagline:'尼罗河穿过狭窄峡谷后，在乌干达草原上形成壮观瀑布',intro:'默奇森瀑布国家公园是乌干达最大的保护区。尼罗河在这里被压入狭窄峡谷，然后形成强大的瀑布。乘船、河岸野生动物和广阔草原共同构成东非最独特的景观之一。',history:'公园于1952年建立，是维多利亚尼罗河沿岸更大保护景观的一部分。瀑布和河流走廊长期以来都是乌干达北部的重要地标。',bestSeason:'6月至9月和12月至2月是受欢迎的旱季。水位和植被全年变化，因此瀑布和河流景色也会随季节不同。',wildlifeHighlights:['河马和尼罗河鳄鱼','大象、长颈鹿和水牛','狮子及其他草原捕食者','尼罗河乘船Safari与瀑布观景点'],faqs:[{q:'默奇森瀑布只是看瀑布吗？',a:'不是。陆地Safari和尼罗河游船都是主要亮点，有机会看到大象、长颈鹿、水牛、河马和鳄鱼。'},{q:'它如何安排进乌干达旅行？',a:'可以与黑猩猩或大猩猩体验结合，形成草原、河流和雨林兼具的线路。'}]},
    akagera:{name:'Akagera',tagline:'湖泊、纸莎草湿地与正在恢复的卢旺达Big Five生态系统',intro:'阿卡盖拉国家公园是卢旺达山地森林之外的草原世界。起伏平原、湖泊、纸莎草湿地和林地为大象、水牛、长颈鹿、斑马、羚羊和不断增长的捕食者种群提供栖息地。伊赫马湖乘船Safari带来不同视角。',history:'阿卡盖拉建立于1934年，后来在冲突和人口流离期间遭受严重的野生动物损失。生态恢复和重新引入项目帮助重建了生态系统，包括狮子和黑犀牛的回归。',bestSeason:'6月至9月通常更干燥，适合观兽。3月至5月更湿润、更绿；10月至2月则可能非常适合观鸟和欣赏葱郁景色。',wildlifeHighlights:['Big Five恢复生态区','伊赫马湖的河马和鳄鱼','长颈鹿、斑马、大象和水牛','纸莎草湿地与丰富鸟类'],faqs:[{q:'阿卡盖拉可以与大猩猩徒步结合吗？',a:'可以。卢旺达旅行可以将阿卡盖拉草原与火山国家公园的大猩猩或金丝猴体验结合。'},{q:'阿卡盖拉适合短途Safari吗？',a:'适合。紧凑的道路网络以及湖泊和草原的组合非常适合两到三天。'}]},
  },
  sw: {
    samburu:{name:'Samburu',tagline:'Uzuri wa maeneo makavu, viumbe adimu wa kaskazini na Mto Ewaso Ng’iro',intro:'Hifadhi ya Taifa ya Samburu inatofautiana sana na hifadhi zenye unyevunyevu zaidi kusini mwa Kenya: vilima vya miamba, mitende ya doum na tambarare za dhahabu hukutana karibu na Mto Ewaso Ng’iro. Inajulikana kwa Samburu Special Five — pundamilia wa Grevy, twiga mwenye matundu, gerenuk, mbuni wa Somalia na oryx — pamoja na simba, chui, tembo na mbwa mwitu wa Afrika.',history:'Samburu ilianzishwa kama eneo linalolindwa mwaka 1985. Eneo hili limekuwa nyumbani kwa jamii za wafugaji wa Samburu kwa muda mrefu, ambao maarifa yao ya maji ya msimu, malisho na wanyamapori yanaendelea kuhusiana kwa karibu na mfumo wa ikolojia.',bestSeason:'Juni–Oktoba na Januari–Februari ni vipindi maarufu vya kiangazi, wakati wanyama hukusanyika karibu na Ewaso Ng’iro. Misimu ya kijani huleta mandhari ya kuvutia na ndege wahamiaji.',wildlifeHighlights:['Samburu Special Five','Tembo kando ya Mto Ewaso Ng’iro','Chui, simba na mbwa mwitu wa Afrika','Twiga wenye matundu na pundamilia wa Grevy'],faqs:[{q:'Samburu inatofautianaje na Mara?',a:'Samburu ina mandhari kame zaidi ya kaskazini na aina kadhaa za wanyamapori ambazo ni nadra kusini mwa Kenya, hivyo ni nyongeza nzuri kwa Mara.'},{q:'Samburu inaweza kuunganishwa na hifadhi nyingine?',a:'Ndiyo. Inaunganishwa vizuri sana na Ol Pejeta, Mount Kenya au Lake Nakuru katika mzunguko mrefu wa Kenya.'}]},
    'lake-nakuru':{name:'Lake Nakuru',tagline:'Miamba ya Bonde la Ufa, vifaru na ziwa maarufu kwa flamingo',intro:'Hifadhi ya Taifa ya Lake Nakuru iko kuzunguka ziwa lenye chumvi kidogo katika Bonde Kuu la Ufa. Nyanda za majani, miamba, misitu ya mikaratusi na maeneo oevu huifanya kuwa sehemu ndogo lakini yenye wanyamapori wengi, hasa vifaru weusi na weupe, twiga wa Rothschild na ndege wa majini.',history:'Eneo la Lake Nakuru lilikuwa hifadhi ya taifa mwaka 1968. Ziwa lilipata umaarufu duniani kwa makundi makubwa ya flamingo, huku juhudi za uhifadhi baadaye zikifanya eneo hili kuwa muhimu kwa uhifadhi wa vifaru.',bestSeason:'Juni–Oktoba na Januari–Februari ni vipindi vya kiangazi vinavyofaa kutazama wanyamapori. Idadi ya flamingo hubadilika kulingana na kiwango cha maji, hali ya ziwa na upatikanaji wa chakula.',wildlifeHighlights:['Vifaru weusi na weupe','Twiga wa Rothschild','Flamingo na pelican wakati hali inafaa','Simba, chui, nyati na waterbuck'],faqs:[{q:'Je, flamingo huwa Lake Nakuru kila wakati?',a:'Hapana. Idadi yao hubadilika kulingana na maji na chakula. Hifadhi bado ni bora kwa vifaru, twiga na wanyamapori wengine.'},{q:'Tunapaswa kukaa kwa muda gani?',a:'Siku nzima au usiku mmoja inafaa sana unapounganisha Nakuru na Masai Mara au maeneo mengine ya Bonde la Ufa.'}]},
    'naivasha-hells-gate':{name:'Lake Naivasha & Hell’s Gate',tagline:'Maji baridi, miamba ya volkano na mojawapo ya matukio bora ya adventure Kenya',intro:'Lake Naivasha ni ziwa la maji baridi katika Bonde la Ufa, likizungukwa na mikaratusi, mashamba ya maua na mandhari ya volkano. Hell’s Gate iliyo karibu ni ya kipekee kwa sababu katika maeneo yaliyoteuliwa unaweza kuchunguza kwa miguu au baiskeli, kati ya miamba mirefu, jotoardhi na pundamilia, twiga na nyati.',history:'Naivasha imekuwa sehemu ya mandhari ya ufugaji na kilimo ya Bonde la Ufa kwa muda mrefu. Hell’s Gate ilitangazwa hifadhi ya taifa mwaka 1984 na jina lake linatokana na uwazi mwembamba kati ya miamba.',bestSeason:'Januari–Februari na Juni–Oktoba ni maarufu kwa njia kavu zaidi na mwonekano mzuri. Misimu ya kijani inaweza kuwa ya kuvutia sana kwa mandhari na ndege.',wildlifeHighlights:['Pundamilia, twiga na nyati','Kiboko katika Lake Naivasha','Ufukwe wa maji baridi wenye ndege wengi','Baiskeli na matembezi kati ya miamba ya volkano'],faqs:[{q:'Tunaweza kutembea Hell’s Gate?',a:'Ndiyo, katika maeneo yaliyoteuliwa na kwa mwongozo unaofaa wa eneo. Ni mojawapo ya hifadhi rahisi zaidi Kenya kwa adventure ya miguu.'},{q:'Naivasha inafaa familia?',a:'Ndiyo. Ziwa, matembezi mepesi, safari za mashua na baiskeli Hell’s Gate huleta utofauti kwenye safari ya familia.'}]},
    'mount-kenya':{name:'Mount Kenya',tagline:'Misitu ya milimani, mabonde ya alpine na kilele cha pili kwa urefu Afrika',intro:'Hifadhi ya Taifa ya Mount Kenya inapitia misitu ya milimani, mianzi na nyanda za juu kuelekea vilele vya volkano. Miteremko ya chini ni makazi ya tembo na nyati, huku maeneo ya juu yakionyesha mimea ya alpine, kuta za miamba na mabaki ya barafu.',history:'Mount Kenya ni volkano ya kale iliyokufa na mlima mtakatifu katika utamaduni wa Kikuyu. Hifadhi ya taifa na hifadhi ya misitu inalinda mifumo yake ya kipekee, na mlima umetambuliwa kama Urithi wa Dunia wa UNESCO tangu 1997.',bestSeason:'Januari–Februari na Juni–Septemba kwa kawaida hufaa kwa trekking kwa sababu huwa pakavu zaidi. Hali ya hewa ya mlima inaweza kubadilika haraka wakati wowote.',wildlifeHighlights:['Tembo na nyati katika eneo la misitu','Colobus na nyani wengine wa misitu','Mimea ya alpine na mandhari ya juu','Aina nyingi za ndege wa milimani'],faqs:[{q:'Mount Kenya ni kwa wapandaji wenye uzoefu tu?',a:'Hapana. Tunaweza kupanga uzoefu wa misitu na nyanda za juu kwa wasafiri wanaotaka mandhari bila kupanda kilele cha juu zaidi.'},{q:'Inaweza kuunganishwa na safari?',a:'Ndiyo. Mount Kenya inaunganishwa vizuri na Samburu, Ol Pejeta, Lake Nakuru na Masai Mara.'}]},
    serengeti:{name:'Serengeti',tagline:'Tambarare zisizo na mwisho, ardhi ya wanyama walao nyama na sehemu ya kusini ya Uhamaji Mkuu',intro:'Hifadhi ya Taifa ya Serengeti ni mojawapo ya mandhari maarufu za wanyamapori Afrika: tambarare kubwa zenye nyasi, kopje, njia za mito na misitu. Inajulikana kwa wanyama walao nyama wanaoishi humo na uhamaji wa kila mwaka wa nyumbu, pundamilia na swala katika mfumo wa Serengeti–Mara.',history:'Serengeti ikawa hifadhi ya taifa mwaka 1951 na baadaye ikaunganishwa katika mfumo mpana wa uhifadhi pamoja na Ngorongoro. Jina Serengeti linatokana na usemi wa Maasai unaotafsiriwa mara nyingi kama “tambarare zisizo na mwisho”.',bestSeason:'Juni–Oktoba ni maarufu kwa kiangazi na shughuli za uhamaji kaskazini. Januari–Machi inaweza kuwa bora kusini wakati wa kuzaliwa kwa ndama, ingawa muda hubadilika kila mwaka.',wildlifeHighlights:['Makundi ya Uhamaji Mkuu','Simba, duma na chui','Idadi kubwa ya tembo na nyati','Mamba na viboko katika mifumo ya mito'],faqs:[{q:'Serengeti ni sawa na Masai Mara?',a:'Hapana. Ni maeneo tofauti yaliyolindwa nchini Tanzania na Kenya, lakini ni sehemu za mfumo mmoja wa ikolojia na hushirikiana uhamaji wa kila mwaka.'},{q:'Uhamaji wa Serengeti hutokea lini?',a:'Unasogea kila wakati katika mfumo wa ikolojia. Kuzaliwa kusini huhusishwa zaidi na Januari–Machi, huku kuvuka mito kaskazini kukihusishwa na miezi ya baadaye.'}]},
    ngorongoro:{name:'Ngorongoro Crater',tagline:'Kaldira ya volkano yenye mkusanyiko mkubwa wa wanyamapori Afrika',intro:'Ngorongoro Crater ni kaldira kubwa la volkano ambalo nyanda, misitu, ziwa na maeneo oevu yaliyomo ndani yake yana wanyamapori wengi sana. Kushuka kwenye crater huhisi kama kuingia kwenye ukumbi wa asili, ambapo simba na fisi huzunguka tambarare na wanyama walao majani hutembea kati ya maji na malisho.',history:'Crater iliundwa baada ya volkano kubwa kuanguka takriban miaka milioni mbili hadi tatu iliyopita. Ngorongoro Conservation Area ilianzishwa mwaka 1959 na inaunganisha uhifadhi wa wanyamapori, jamii za wafugaji na urithi wa kitamaduni.',bestSeason:'Juni–Oktoba ni kipindi maarufu cha kiangazi kwa mwonekano mzuri na wanyama waliokusanyika. Januari–Machi huleta mandhari ya kijani na shughuli za kuzaliwa katika mfumo mpana.',wildlifeHighlights:['Idadi kubwa ya simba na fisi','Tembo na makundi makubwa ya nyati','Viboko katika maeneo oevu ya crater','Moja ya maeneo bora kaskazini mwa Tanzania kuona vifaru'],faqs:[{q:'Tunaweza kulala ndani ya crater?',a:'Malazi mengi yako kwenye ukingo wa crater au eneo la uhifadhi linalozunguka, si chini ya crater. Safari hushuka wakati unaoruhusiwa.'},{q:'Tunahitaji muda gani?',a:'Safari ya crater inaweza kufanyika kwa siku moja, hasa ikiunganishwa na Serengeti au Tarangire.'}]},
    tarangire:{name:'Tarangire',tagline:'Mibuyu, makundi makubwa ya tembo na mto unaokuwa chanzo cha maisha wakati wa kiangazi',intro:'Hifadhi ya Taifa ya Tarangire inajulikana kwa mibuyu mikubwa, maeneo oevu ya msimu na mto unaovutia wanyamapori wakati wa miezi ya kiangazi. Tembo ni kivutio kikuu, lakini pia kuna twiga, pundamilia, nyumbu, paka wakubwa na ndege wengi.',history:'Tarangire ikawa hifadhi ya taifa mwaka 1970 baada ya miaka kama hifadhi ya wanyamapori iliyolindwa. Mto Tarangire na njia za uhamaji zinazouzunguka ni muhimu kwa ikolojia ya hifadhi, hasa wakati wa kiangazi Tanzania.',bestSeason:'Juni–Oktoba ni bora sana kwa sababu wanyama hukusanyika karibu na Mto Tarangire na vyanzo vya maji vilivyosalia. Novemba–Mei huleta mandhari ya kijani na ndege wengi.',wildlifeHighlights:['Makundi makubwa ya tembo','Mandhari ya mibuyu ya kale','Simba, chui na duma','Ndege wengi na aina zinazohama kwa msimu'],faqs:[{q:'Kwa nini kuchagua Tarangire ikiwa tunatembelea Serengeti?',a:'Tarangire ina mandhari tofauti, mibuyu mikubwa na uzoefu mzuri wa kuona tembo, hivyo ni tofauti nzuri katika safari ya kaskazini mwa Tanzania.'},{q:'Tarangire inafaa safari fupi?',a:'Ndiyo. Ziara ya siku moja au mbili kutoka eneo la Arusha inafanya kazi vizuri.'}]},
    zanzibar:{name:'Zanzibar',tagline:'Historia ya Kiswahili, visiwa vya viungo na fukwe za turquoise za Bahari ya Hindi',intro:'Zanzibar ni nyongeza ya asili ya ufukweni baada ya safari ya kaskazini mwa Tanzania: miamba ya matumbawe, fukwe nyeupe, mashamba ya viungo na mitaa ya Stone Town huleta mabadiliko makubwa ya hisia baada ya siku porini.',history:'Zanzibar ilikuwa kituo muhimu cha biashara katika Bahari ya Hindi, kikichangiwa na tamaduni za Afrika, Waarabu, Waajemi, Wahindi na Wazungu. Stone Town huhifadhi historia hii ya Kiswahili na ni Urithi wa Dunia wa UNESCO.',bestSeason:'Juni–Oktoba ni kipindi maarufu cha kiangazi. Desemba–Februari pia huwa na joto na hali nzuri kwa ujumla. Aprili–Mei huleta mvua ndefu na wageni wachache.',wildlifeHighlights:['Dolphin na maisha ya miamba','Colobus wekundu Unguja','Bustani za matumbawe na fukwe za Bahari ya Hindi','Stone Town na urithi wa njia za viungo'],faqs:[{q:'Zanzibar inaweza kuunganishwa na safari?',a:'Ndiyo. Ni nyongeza rahisi ya ufukweni baada ya Serengeti, Ngorongoro au Tarangire kutokana na safari za ndege za kawaida.'},{q:'Zanzibar ni fukwe tu?',a:'Hapana. Stone Town, mashamba ya viungo, safari za dhow, miamba na uzoefu wa kitamaduni hufanya iwe destination kamili.'}]},
    'queen-elizabeth':{name:'Queen Elizabeth National Park',tagline:'Maji ya Kazinga Channel, maziwa ya crater na safari ya savana ya Uganda',intro:'Hifadhi ya Taifa ya Queen Elizabeth iko kati ya Lake Edward na Lake George na inaunganisha savana, maziwa ya crater, misitu na Kazinga Channel yenye wanyamapori wengi. Safari za mashua huonyesha viboko, mamba na ndege wengi wa maji, huku safari za ardhini zikitafuta tembo, simba, nyati na Uganda kob.',history:'Hifadhi ilianzishwa mwaka 1954 na kuitwa kwa heshima ya Queen Elizabeth II. Iko katika Albertine Rift, mojawapo ya maeneo yenye bioanuwai kubwa Afrika.',bestSeason:'Juni–Septemba na Desemba–Februari ni maarufu kwa hali kavu na kutazama wanyamapori. Miezi ya mvua inaweza kuwa mizuri kwa mandhari na ndege.',wildlifeHighlights:['Simba wanaopanda miti katika Ishasha','Viboko na mamba katika Kazinga Channel','Tembo, nyati na Uganda kob','Aina nyingi sana za ndege'],faqs:[{q:'Kwa nini Queen Elizabeth badala ya Kenya?',a:'Inatoa mandhari tofauti ya Albertine Rift, uzoefu bora wa mashua na ufikiaji wa maeneo ya misitu na nyani ya Uganda.'},{q:'Inaweza kuunganishwa na gorilla trekking?',a:'Ndiyo. Queen Elizabeth ni kituo cha kawaida katika safari ndefu zinazoelekea Bwindi.'}]},
    bwindi:{name:'Bwindi Impenetrable Forest',tagline:'Msitu wa zamani wa mvua na moja ya mikutano ya ajabu zaidi na gorilla wa milimani',intro:'Bwindi ni msitu wa zamani wa mvua wenye miteremko mikali, maarufu kwa trekking ya gorilla wa milimani. Mimea minene, milima yenye ukungu na bioanuwai ya kipekee huifanya iwe tofauti kabisa na hifadhi za savana. Trekking ni changamoto lakini ina thawabu kubwa.',history:'Bwindi ilitangazwa hifadhi ya taifa mwaka 1991 na kuwa Urithi wa Dunia wa UNESCO mwaka 1994. Utalii wa uhifadhi husaidia kulinda gorilla na jamii jirani.',bestSeason:'Juni–Agosti na Desemba–Februari hupendelewa mara nyingi kwa sababu njia zinaweza kuwa na unyevunyevu mdogo, lakini trekking hufanyika mwaka mzima na mvua inawezekana wakati wowote.',wildlifeHighlights:['Gorilla wa milimani','Nyani wa dhahabu na jamii nyingine za nyani karibu','Ndege wa Albertine Rift wasiopatikana kwingine','Msitu wa zamani wa milimani'],faqs:[{q:'Gorilla trekking ni ngumu kimwili?',a:'Inaweza kuwa ngumu. Muda na ardhi hutegemea familia ya gorilla na hali ya siku. Jiandae kwa njia za msitu zenye mwinuko na matope.'},{q:'Ni mapema kiasi gani kupanga vibali vya gorilla?',a:'Vibali ni vichache na vinahitajika sana, hivyo vinapaswa kupatikana mapema kupitia mamlaka husika za Uganda au mwendeshaji anayeaminika.'}]},
    'murchison-falls':{name:'Murchison Falls',tagline:'Mto Nile unapita kwenye korongo nyembamba kabla ya kumwaga nguvu zake kwenye savana ya Uganda',intro:'Hifadhi ya Taifa ya Murchison Falls ndiyo eneo kubwa zaidi lililolindwa Uganda. Mto Nile unapita kwenye korongo nyembamba kabla ya kuanguka kwa nguvu kwenye maporomoko. Safari za mashua, wanyamapori wa kando ya mto na tambarare kubwa za savana huunda mandhari ya kipekee Afrika Mashariki.',history:'Hifadhi ilitangazwa mwaka 1952 na ni sehemu ya eneo kubwa lililolindwa kando ya Victoria Nile. Maporomoko na ukanda wa mto ni alama muhimu za kaskazini mwa Uganda kwa vizazi.',bestSeason:'Juni–Septemba na Desemba–Februari ni vipindi maarufu vya kiangazi. Kiwango cha maji na mimea hubadilika mwaka mzima, hivyo mandhari ya maporomoko pia hubadilika.',wildlifeHighlights:['Viboko na mamba wa Nile','Tembo, twiga na nyati','Simba na wanyama wengine walao nyama wa savana','Safari ya mashua kwenye Nile na eneo la kutazama maporomoko'],faqs:[{q:'Murchison Falls ni maporomoko tu?',a:'Hapana. Safari za ardhini na safari ya mashua kwenye Nile ni vivutio vikuu, zikiwa na nafasi nzuri ya kuona tembo, twiga, nyati, viboko na mamba.'},{q:'Inaingiaje katika safari ya Uganda?',a:'Inaweza kuunganishwa na uzoefu wa sokwe au gorilla ili kuunda safari inayochanganya savana, mto na msitu wa mvua.'}]},
    akagera:{name:'Akagera',tagline:'Maziwa, maeneo oevu ya papyrus na mfumo wa Big Five unaorejea Rwanda',intro:'Hifadhi ya Taifa ya Akagera ni upande wa savana wa misitu ya milimani ya Rwanda. Tambarare, maziwa, maeneo oevu ya papyrus na misitu huunga mkono tembo, nyati, twiga, pundamilia, swala na wanyama walao nyama wanaoongezeka. Safari ya mashua katika Lake Ihema huleta mtazamo tofauti.',history:'Akagera ilianzishwa mwaka 1934 na baadaye ikapoteza wanyamapori wengi wakati wa migogoro na uhamishaji wa watu. Programu za kurejesha na kurudisha wanyama zimejenga upya mfumo wa ikolojia, ikiwa ni pamoja na kurudi kwa simba na vifaru weusi.',bestSeason:'Juni–Septemba kwa kawaida huwa kavu zaidi na nzuri kwa kuona wanyamapori. Machi–Mei huwa na unyevu na kijani zaidi, huku Oktoba–Februari ikiwa mizuri kwa ndege na mandhari yenye kijani.',wildlifeHighlights:['Eneo la kurejesha Big Five','Viboko na mamba katika Lake Ihema','Twiga, pundamilia, tembo na nyati','Maeneo oevu ya papyrus na ndege wengi'],faqs:[{q:'Akagera inaweza kuunganishwa na gorilla trekking?',a:'Ndiyo. Safari ya Rwanda inaweza kuunganisha savana ya Akagera na gorilla au nyani wa dhahabu katika Volcanoes National Park.'},{q:'Akagera inafaa safari fupi?',a:'Ndiyo. Mtandao wake wa barabara ni mfupi na mchanganyiko wa ziwa na savana unafaa kwa siku mbili au tatu.'}]},
  },
};

export function getExpandedLocalizedDestination(destination: Destination, locale: Locale): Destination {
  const translated = expandedDestinationTranslations[locale]?.[destination.slug];
  return translated ? ({ ...destination, ...translated } as Destination) : destination;
}
